function bepAppendTimeHeader(panel, value, x, width) {
  var header = bepText(value, B, 14, { lh:22, a:0.65 });
  header.x = x + Math.round((width - header.width) / 2);
  header.y = 4;
  panel.appendChild(header);
  var div = bepRect(width, 1, B, { x:x, y:30 });
  div.opacity = 0.10;
  panel.appendChild(div);
}

function bepAppendTimeColumns(panel, x, y, selected) {
  var values = ['01', '02', '03', '04', '05', '06', '07'];
  var colW = 56;
  var rowYs = [0, 34, 68, 105, 141, 175, 209];
  [55, 111].forEach(function(dx) {
    var line = bepRect(1, 242, B, { x:x + dx, y:y - 3 });
    line.opacity = 0.10;
    panel.appendChild(line);
  });
  [0, 1, 2].forEach(function(col) {
    var sel = bepRect(colW, 32, BEP_C.primary, { x:x + col * colW, y:y + 100 });
    panel.appendChild(sel);
    values.forEach(function(value, idx) {
      var isSel = value === selected;
      var t = bepText(value, isSel ? BEP_C.white : B, 14, { lh:22, a:isSel ? 1 : 0.65 });
      t.x = x + col * colW + Math.round((colW - t.width) / 2);
      t.y = y + rowYs[idx];
      panel.appendChild(t);
    });
  });
  var thumb = bepRect(4, 40, bepHex('#D8D8D8'), { x:x + 162, y:y + 82, r:4 });
  panel.appendChild(thumb);
}

