/**
 * 标示 Tag（Figma实测：底色/边框/点/动态/添加）
 * type: 'enabled'|'disabled'|'info'|'success'|'warning'|'danger'|'inactive'
 * style: 'solid'|'outline'|'dot'|'closable'|'add'（默认 outline）
 *        也可传 opts 对象：{ style, closable, add }
 */
function bepTag(label, type, style) {
  var opts = {};
  if (typeof style === 'object' && style !== null) {
    opts = style;
    style = opts.style;
  }
  style = style || (opts.add ? 'add' : (opts.closable ? 'closable' : 'outline'));
  type = type || 'info';
  label = label || '';
  var OUTLINE = {
    enabled:  { bg: bepHex('EBF8EC'), bd: bepHex('D8F1D8'), fg: bepHex('3BBB3E') },
    disabled: { bg: B,                bd: B,                 fg: B,       bgA:0.04, bdA:0.15, fgA:0.25 },
    info:     { bg: bepHex('E6F0F5'), bd: bepHex('CCE2EB'),  fg: BEP_C.primary },
    success:  { bg: bepHex('EBF8EC'), bd: bepHex('D8F1D8'),  fg: bepHex('3BBB3E') },
    warning:  { bg: bepHex('FFF6EC'), bd: bepHex('FFEDDA'),  fg: bepHex('FFA645') },
    danger:   { bg: bepHex('FFEFEF'), bd: bepHex('FFDFDD'),  fg: bepHex('FE5E54') },
    inactive: { bg: B,                bd: B,                 fg: B,      bgA:0.04, bdA:0.15, fgA:0.25 },
  };
  var SOLID = {
    enabled:  { bg: BEP_C.success,  fg: BEP_C.white },
    disabled: { bg: B,               fg: BEP_C.white, bgA:0.25 },
    info:     { bg: BEP_C.primary,   fg: BEP_C.white },
    success:  { bg: BEP_C.success,   fg: BEP_C.white },
    warning:  { bg: BEP_C.warning,   fg: BEP_C.white },
    danger:   { bg: BEP_C.danger,    fg: BEP_C.white },
    inactive: { bg: B,               fg: BEP_C.white, bgA:0.25 },
  };
  var DOT = {
    enabled:  { dot: BEP_C.success },
    disabled: { dot: B, dotA:0.25 },
    info:     { dot: BEP_C.primary },
    success:  { dot: BEP_C.success },
    warning:  { dot: BEP_C.warning },
    danger:   { dot: BEP_C.danger },
    inactive: { dot: B, dotA:0.25 },
  };

  if (style === 'dot') {
    var dotCfg = DOT[type] || DOT.info;
    var dotText = bepText(label, B, 14, { lh:22, a:0.65 });
    var dotW = 14 + dotText.width;
    dotText.remove();
    var dotTag = bepFrame(dotW, 22, { name:'DotTag/' + label, clip:false });
    dotTag.fills = [];
    var dot = bepFrame(6, 6, { name:'Dot', clip:true });
    dot.cornerRadius = 3;
    dot.fills = bepSolid(dotCfg.dot, dotCfg.dotA !== undefined ? dotCfg.dotA : 1);
    dot.x = 0; dot.y = 8;
    dotTag.appendChild(dot);
    var dt = bepText(label, B, 14, { lh:22, a:0.65, x:14, y:0 });
    dotTag.appendChild(dt);
    return dotTag;
  }

  if (style === 'closable' || style === 'add') {
    var dynamicLabel = label || (style === 'add' ? '新标示' : '');
    var dTmp = bepText(dynamicLabel, B, 12, { lh:20 });
    var dTextW = dTmp.width;
    dTmp.remove();
    var iconSize = 12;
    var dW = dTextW + 16 + iconSize + 4;
    var dTag = bepFrame(dW, 22, { name:(style === 'add' ? 'AddTag/' : 'ClosableTag/') + dynamicLabel, clip:true });
    dTag.fills = bepSolid(B, 0.04);
    dTag.strokes = bepSolid(B, 0.15);
    dTag.strokeWeight = 1;
    dTag.strokeAlign = 'INSIDE';
    dTag.cornerRadius = 2;
    var firstIcon = style === 'add';
    if (firstIcon) {
      var addIco = bepIcon('Line/Add', iconSize, BEP_C.primary);
      if (addIco) { addIco.x = 8; addIco.y = 5; dTag.appendChild(addIco); }
      var addText = bepText(dynamicLabel, B, 12, { lh:20, a:0.65, x:24, y:1 });
      dTag.appendChild(addText);
    } else {
      var cText = bepText(dynamicLabel, B, 12, { lh:20, a:0.65, x:8, y:1 });
      dTag.appendChild(cText);
      var closeIco = bepIcon('Fill/Close', iconSize, B);
      if (closeIco) {
        closeIco.opacity = 0.25;
        closeIco.x = 8 + dTextW + 4;
        closeIco.y = 5;
        dTag.appendChild(closeIco);
      }
    }
    return dTag;
  }

  var cfg = (style === 'solid' ? SOLID : OUTLINE)[type] || OUTLINE['info'];
  // 先测量文字宽度
  var tmpT = bepText(label, BEP_C.black, 12, { lh:20 });
  var tw = tmpT.width;
  tmpT.remove();
  var tagW = tw + 16;  // 左右各8px
  var tag = bepFrame(tagW, 22, { name:'Tag/' + label, clip:true });
  tag.fills       = bepSolid(cfg.bg, cfg.bgA !== undefined ? cfg.bgA : 1);
  tag.cornerRadius = 2;
  if (style === 'outline') {
    tag.strokes     = bepSolid(cfg.bd, cfg.bdA !== undefined ? cfg.bdA : 1);
    tag.strokeWeight = 1;
    tag.strokeAlign = 'INSIDE';
  }
  var t = bepText(label, cfg.fg, 12, { lh:20, a: cfg.fgA !== undefined ? cfg.fgA : 1 });
  t.x = 8; t.y = 1;
  tag.appendChild(t);
  return tag;
}

/**
 * 数字输入框（InputNumber，带右侧上下步进器）
 * value: 当前数字，未传默认显示 0
 * opts: { state:'default'|'hover'|'complete'|'error', disabled, error, errorText, prefixText, suffixText }
 */
function bepInputNumber(value, width, height, opts) {
  if (typeof height === 'object') {
    opts = height;
    height = 32;
  }
  width  = width  || 160;
  height = height || 32;
  opts = opts || {};

  var state = opts.disabled ? 'disabled' : (opts.error ? 'error' : (opts.state || (value !== undefined && value !== null && String(value) !== '' ? 'complete' : 'default')));
  var hasPrefix = opts.prefixText !== undefined && opts.prefixText !== null && String(opts.prefixText) !== '';
  var hasSuffix = opts.suffixText !== undefined && opts.suffixText !== null && String(opts.suffixText) !== '';
  var prefixW = hasPrefix ? Math.max(50, bepMeasureText(opts.prefixText, 14) + 22) : 0;
  var suffixW = hasSuffix ? Math.max(52, bepMeasureText(opts.suffixText, 14) + 24) : 0;
  var stepperW = 23;
  var bodyX = hasPrefix ? prefixW - 1 : 0;
  var bodyW = width - bodyX - suffixW;
  var wrap = bepFrame(width, opts.errorText ? height + 20 : height, { name:'InputNumber/' + state, clip:false });
  wrap.fills = [];

  if (hasPrefix) {
    var pre = bepInputNumberSegment(opts.prefixText, prefixW, height, 'prefix', state);
    pre.x = 0; pre.y = 0; wrap.appendChild(pre);
  }

  var body = bepInputNumberBody(value, bodyW, height, state, {
    clipLeftRadius: hasPrefix,
    clipRightRadius: hasSuffix,
    reserveErrorIcon: state === 'error',
    textAlpha: opts.textAlpha
  });
  body.x = bodyX; body.y = 0; wrap.appendChild(body);

  if (state === 'error') {
    var errIco = bepIcon('Fill/Abnormal', 16, BEP_C.danger);
    if (errIco) {
      errIco.x = bodyX + bodyW - stepperW - 16 - 8;
      errIco.y = Math.round((height - 16) / 2);
      wrap.appendChild(errIco);
    }
  }

  if (hasSuffix) {
    var suf = bepInputNumberSegment(opts.suffixText, suffixW, height, 'suffix', state);
    suf.x = width - suffixW; suf.y = 0; wrap.appendChild(suf);
  }

  if (opts.errorText) {
    var err = bepText(opts.errorText, BEP_C.danger, 12, { lh:16, x:0, y:height + 4 });
    wrap.appendChild(err);
  }
  return wrap;
}

function bepInputNumberBody(value, width, height, state, opts) {
  opts = opts || {};
  var box = bepFrame(width, height, { name:'InputNumberBody', r:2, clip:true });
  box.fills = bepSolid(state === 'disabled' ? B : BEP_C.white, state === 'disabled' ? 0.04 : 1);
  var strokeColor = state === 'error' ? BEP_C.danger : (state === 'hover' || state === 'complete-hover' ? BEP_C.primary : B);
  var strokeA = state === 'error' || state === 'hover' || state === 'complete-hover' ? 1 : 0.15;
  box.strokes = bepSolid(strokeColor, strokeA);
  box.strokeWeight = 1;
  box.strokeAlign = 'INSIDE';
  if (opts.clipLeftRadius) {
    box.topLeftRadius = 0;
    box.bottomLeftRadius = 0;
  }
  if (opts.clipRightRadius) {
    box.topRightRadius = 0;
    box.bottomRightRadius = 0;
  }

  var stepperW = 23;
  var text = value !== undefined && value !== null && String(value) !== '' ? String(value) : '0';
  var defaultAlpha = state === 'disabled' ? 0.65 : (state === 'complete' || state === 'complete-hover' ? 0.65 : 0.85);
  var rightPad = stepperW + 12 + (opts.reserveErrorIcon ? 24 : 0);
  var t = bepText(text, B, 14, { lh:22, a: opts.textAlpha !== undefined ? opts.textAlpha : defaultAlpha });
  t.x = 12;
  t.y = Math.round((height - 22) / 2);
  t.resize(Math.max(width - 12 - rightPad, 8), 22);
  t.textAutoResize = 'NONE';
  t.textTruncation = 'ENDING';
  box.appendChild(t);

  var stepper = bepInputNumberStepper(stepperW, height, state);
  stepper.x = width - stepperW;
  stepper.y = 0;
  box.appendChild(stepper);
  return box;
}

function bepInputNumberStepper(width, height, state) {
  var stepper = bepFrame(width, height, { name:'InputNumberStepper', clip:true });
  stepper.fills = [];
  var half = (height - 2) / 2;
  var top = bepRect(width - 1, half, B, { a:0.04, x:1, y:1 });
  var bottom = bepRect(width - 1, half, B, { a:0.04, x:1, y:height - half - 1 });
  stepper.appendChild(top);
  stepper.appendChild(bottom);
  stepper.appendChild(bepRect(1, height - 2, B, { a:0.15, x:0, y:1 }));
  stepper.appendChild(bepRect(width - 1, 1, B, { a:0.15, x:1, y:Math.round(height / 2) }));
  var icoA = state === 'disabled' ? 0.25 : 0.65;
  var upIco = bepIcon('Line/PutAway-Arrow', 12, B);
  if (upIco) { upIco.x = 6; upIco.y = 2; upIco.opacity = icoA; stepper.appendChild(upIco); }
  var dnIco = bepIcon('Line/DropDown-Arrow', 12, B);
  if (dnIco) { dnIco.x = 6; dnIco.y = height - 14; dnIco.opacity = icoA; stepper.appendChild(dnIco); }
  return stepper;
}

function bepInputNumberSegment(label, width, height, kind, state) {
  var seg = bepFrame(width, height, { name:kind === 'prefix' ? 'InputNumberPrefix' : 'InputNumberSuffix', clip:true });
  seg.fills = bepSolid(state === 'disabled' ? B : BEP_C.white, state === 'disabled' ? 0.04 : 1);
  seg.strokes = bepSolid(B, 0.15);
  seg.strokeWeight = 1;
  seg.strokeAlign = 'INSIDE';
  var t = bepText(label, bepHex('#666666'), 14, { lh:22 });
  t.x = Math.round((width - t.width) / 2);
  t.y = Math.round((height - 22) / 2);
  seg.appendChild(t);
  return seg;
}

/**
 * 组合数字输入框：左侧选择器 + 右侧数字输入框。
 */
function bepInputNumberGroup(selectPlaceholder, value, width, opts) {
  opts = opts || {};
  width = width || 280;
  var height = opts.height || 32;
  var selectW = opts.selectW || 86;
  var inputW = width - selectW + 1;
  var wrap = bepFrame(width, opts.errorText ? height + 20 : height, { name:'InputNumberGroup', clip:false });
  var sel = opts.selectValue
    ? bepInput(selectPlaceholder || '请选择', selectW, height, { value:opts.selectValue, suffixIconKey:'Line/DropDown-Arrow' })
    : bepSelect(selectPlaceholder || '请选择', selectW, height);
  sel.name = opts.selectValue ? 'InputNumberGroupSelect/complete' : 'InputNumberGroupSelect/default';
  sel.x = 0; sel.y = 0; wrap.appendChild(sel);
  var num = bepInputNumber(value, inputW, height, {
    state: opts.inputHover ? 'hover' : opts.state,
    disabled: opts.disabled,
    error: opts.error,
    errorText: opts.errorText,
    textAlpha: opts.textAlpha
  });
  num.x = selectW - 1; num.y = 0; wrap.appendChild(num);
  return wrap;
}

/**
 * 表格空状态占位（当 tableData 为空时使用）
 * tableW : 表格宽度；用于居中对齐
 */
function bepEmptyState(tableW) {
  tableW = tableW || 1152;
  var H  = 120;
  var wrap = bepFrame(tableW, H, { name:'EmptyState' });
  wrap.fills = bepSolid(BEP_C.white);

  // 圆形图标占位
  var circle = bepRect(48, 48, B, { a:0.06, r:24 });
  circle.x = Math.round((tableW - 48) / 2);
  circle.y = 20;
  wrap.appendChild(circle);

  // "暂无数据" 文字
  var txt = bepText('暂无数据', B, 14, { lh:22, a:0.45 });
  txt.x = Math.round((tableW - txt.width) / 2);
  txt.y = 76;
  wrap.appendChild(txt);

  return wrap;
}

// ── § 4b 开关控件 ─────────────────────────────────────────────────────────────

/**
 * BeP 标准开关（Switch）
 * isOn     : true（默认）| false
 * labelOn  : 开启时的文案（默认 '启用'）
 * labelOff : 关闭时的文案（默认 '停用'）
 * opts     : { size:'large'|'middle'|'small', disabled, loading, showText }
 *
 * Figma 真源：0:710 / 2.DataEntry/3.Switch开关
 */
function bepSwitch(isOn, labelOn, labelOff, opts) {
  if (typeof labelOn === 'object') {
    opts = labelOn;
    labelOn = '启用';
    labelOff = '停用';
  } else if (typeof labelOff === 'object') {
    opts = labelOff;
    labelOff = '停用';
  }
  isOn     = (isOn !== false);
  labelOn  = labelOn  || '启用';
  labelOff = labelOff || '停用';
  opts = opts || {};

  var size = opts.size || opts.variant || 'middle';
  if (opts.showText || opts.loading) size = 'middle';
  var specMap = {
    large:  { trackW:48, trackH:26, thumb:22, r:14, font:0,  lh:0  },
    middle: { trackW:42, trackH:22, thumb:18, r:12, font:12, lh:20 },
    small:  { trackW:30, trackH:16, thumb:12, r:8,  font:0,  lh:0  }
  };
  var spec = specMap[size] || specMap.middle;
  var margin = 2;
  var totalW = spec.trackW;
  var totalH = spec.trackH;
  var stateName = isOn ? 'On' : 'Off';
  var name = 'Switch/' + stateName + '/' + size;
  if (opts.showText) name += '/Text';
  if (opts.loading) name += '/Loading';
  if (opts.disabled) name += '/Disabled';

  var wrap = bepFrame(totalW, totalH, { name:name, r:spec.r, clip:true });
  wrap.fills = [];
  if (opts.disabled) {
    wrap.opacity = 0.5;
    wrap.locked = true;
  }

  var trackColor = isOn ? BEP_C.primary : B;
  var track = bepRect(spec.trackW, spec.trackH, trackColor, { r:spec.r });
  if (!isOn) track.opacity = 0.25;
  track.x = 0;
  track.y = 0;
  wrap.appendChild(track);

  if (opts.showText) {
    var text = bepText(isOn ? '开' : '关', BEP_C.white, 12, { lh:20 });
    text.x = isOn ? 8 : 22;
    text.y = 1;
    wrap.appendChild(text);
  }

  var thumb = bepRect(spec.thumb, spec.thumb, BEP_C.white, { r:spec.thumb / 2 });
  thumb.x = isOn ? (spec.trackW - spec.thumb - margin) : margin;
  thumb.y = margin;
  wrap.appendChild(thumb);

  if (opts.loading) {
    var load = bepIcon('Line/Loading', 10, bepHex('#FF0D0D'));
    if (load) {
      load.name = 'LoadingRotating';
      load.x = thumb.x + Math.round((spec.thumb - 10) / 2);
      load.y = thumb.y + Math.round((spec.thumb - 10) / 2);
      wrap.appendChild(load);
    }
  }

  return wrap;
}

// ── § 4c  评分控件 ─────────────────────────────────────────────────────────────

/**
 * BeP 标准评分（Rate）
 * value : 0-5，默认 3
 * opts  : { count, text, showText }
 *
 * Figma 真源：0:710 / 2.DataEntry/13.Rate评分
 */
function bepRate(value, opts) {
  opts = opts || {};
  var count = opts.count || 5;
  value = value === undefined || value === null ? 3 : Number(value);
  value = Math.max(0, Math.min(count, Math.round(value)));
  var showText = opts.showText !== false;
  var textValue = opts.text === undefined ? '一般' : String(opts.text);
  var starSize = 16;
  var starGap = 4;
  var textGap = 16;
  var starsW = count * starSize + (count - 1) * starGap;
  var label = showText ? bepText(textValue, B, 14, { lh:22, a:0.85 }) : null;
  var totalW = starsW + (label ? textGap + label.width : 0);
  var wrap = bepFrame(totalW, 22, { name:'Rate/' + value + '-of-' + count, clip:false });

  for (var i = 0; i < count; i++) {
    var color = i < value ? bepHex('#FFA645') : bepHex('#CCCCCC');
    var star = bepIcon('Fill/Star', starSize, color);
    star.name = i < value ? 'Star-Selected' : 'Star-Unselected';
    star.x = i * (starSize + starGap);
    star.y = 3;
    wrap.appendChild(star);
  }

  if (label) {
    label.x = starsW + textGap;
    label.y = 0;
    wrap.appendChild(label);
  }

  return wrap;
}

// ── § 5  表格 ─────────────────────────────────────────────────────────────────

/**
 * 表头行（SKILL.md: 高48px, 背景rgba(0,0,0,0.04), 底边框rgba(0,0,0,0.06)）
 * cols: [{label, w, align}]  tableW: 总宽
 * opts: { size:'default'|'mini', height }
 */
function bepTableSpec(opts) {
  opts = opts || {};
  var size = opts.size || opts.variant || 'default';
  var h = opts.height || (size === 'mini' ? 40 : 48);
  return {
    size: size,
    h: h,
    padX: size === 'mini' ? 12 : 16,
    lh: 22,
    headerY: Math.round((h - 22) / 2),
    rowY: Math.round((h - 22) / 2),
    bdY: h - 1
  };
}

function bepTableHeader(cols, tableW, opts) {
  var spec = bepTableSpec(opts);
  var hdr = bepFrame(tableW, spec.h, { name:'TableHeader/' + spec.size, clip:true });
  hdr.fills = bepSolid(B, 0.04);
  // 底边框
  var bd = bepRect(tableW, 1, B, { a:0.06, x:0, y:spec.bdY });
  hdr.appendChild(bd);
  var cx = 0;
  cols.forEach(function(col) {
    var cell = bepFrame(col.w, spec.h, { name:'TH/' + col.label });
    cell.x = cx;
    var t = bepText(col.label, B, 14, { style:'Medium', lh:22, a:0.85 });
    t.y = spec.headerY;
    if (col.align === 'center') t.x = Math.round((col.w - t.width) / 2);
    else if (col.align === 'right') t.x = col.w - t.width - spec.padX;
    else t.x = spec.padX;
    cell.appendChild(t);
    // 规范：无列竖线
    hdr.appendChild(cell);
    cx += col.w;
  });
  return hdr;
}

/**
 * 表格数据行（SKILL.md: 高48px, 底边框rgba(0,0,0,0.06)）
 * cells: [{content(string|node), align}]  bgColor: 行背景色（默认透明）
 * 当 cell.content 是字符串时自动创建截断文字节点
 * opts: { size:'default'|'mini', height }
 */
function bepTableRow(cells, cols, tableW, bgColor, opts) {
  if (bgColor && typeof bgColor === 'object' && (bgColor.size || bgColor.variant || bgColor.height)) {
    opts = bgColor;
    bgColor = null;
  }
  var spec = bepTableSpec(opts);
  var row = bepFrame(tableW, spec.h, { name:'Row/' + spec.size, clip:true });
  row.fills = bgColor ? bepSolid(bgColor) : [];
  // 底边框
  row.appendChild(bepRect(tableW, 1, B, { a:0.06, x:0, y:spec.bdY }));
  var cx = 0;
  cells.forEach(function(cell, i) {
    var col = cols[i] || { w:100, align:'left' };
    var cellFrame = bepFrame(col.w, spec.h, { name:'TD' + i });
    cellFrame.x = cx;
    var content = cell.content !== undefined ? cell.content : cell;
    var align = cell.align || col.align || 'left';
    var node;
    if (typeof content === 'string') {
      node = bepTableText(content, B, col.w - spec.padX * 2, {
        a: 0.65,
        alignH: align === 'right' ? 'RIGHT' : (align === 'center' ? 'CENTER' : undefined)
      });
    } else {
      node = content;
    }
    node.y = Math.round((spec.h - (node.height || 22)) / 2);
    if (align === 'center') node.x = Math.round((col.w - (node.width || 60)) / 2);
    else if (align === 'right') node.x = col.w - (node.width || 60) - spec.padX;
    else node.x = spec.padX;
    cellFrame.appendChild(node);
    row.appendChild(cellFrame);
    cx += col.w;
  });
  return row;
}

// ── § 5b 操作列按钮组 ────────────────────────────────────────────────────────

/**
 * 表格操作列按钮组
 * actions : [{label, type}]  type: 'primary'（默认）| 'danger'
 *
 * 规则：
 *   · 操作间距 16px，无分隔线
 *   · 操作列是复合列；建议先用 bepActionMetrics(actionRows) 按操作位置计算子级列宽
 *   · 普通操作：主色 #006D9B；危险操作（删除/禁用等）：#FE5E54
 *   · 最多显示 3 个；超过 3 个时第 3 个替换为"更多"图标（Line/More，竖向三点）
 *   · 操作文字不换行、不省略；父级操作列宽 = 子级列宽之和 + 子级间距 + 左右 16px
 *
 * 使用示例：
 *   var metrics = bepActionMetrics(actionRows);
 *   cols.push({ label:'操作', w:metrics.width + 32 });
 *   bepActionCell([
 *     { label:'编辑',   type:'primary' },
 *     { label:'删除',   type:'danger'  },
 *     { label:'查看',   type:'primary' },
 *     { label:'导出',   type:'primary' },  // 第4个→归入更多
 *   ], { slotWidths: metrics.slotWidths })
 */
function bepNormalizeActions(actions) {
  if (!actions || actions.length === 0) return [];

  var MAX = 3;
  return (actions.length <= MAX)
    ? actions.slice()
    : actions.slice(0, 2).concat([{ label:'__more__', type:'primary' }]);
}

function bepActionItemWidth(action) {
  if (!action) return 0;
  if (action.label === '__more__') return 16;
  var t = bepText(action.label, BEP_C.primary, 14, { lh:22 });
  var w = t.width;
  t.remove();
  return w;
}

function bepActionMetrics(actionRows) {
  var GAP = 16;
  var slotWidths = [];
  (actionRows || []).forEach(function(actions) {
    bepNormalizeActions(actions).forEach(function(action, i) {
      var w = bepActionItemWidth(action);
      slotWidths[i] = Math.max(slotWidths[i] || 0, w);
    });
  });
  var contentW = slotWidths.reduce(function(sum, w, i) {
    return sum + w + (i < slotWidths.length - 1 ? GAP : 0);
  }, 0);
  return { slotWidths: slotWidths, width: contentW };
}

function bepActionCell(actions, opts) {
  opts = opts || {};
  if (!actions || actions.length === 0) return bepFrame(0, 22, { name:'ActionCell' });

  var GAP    = 16;
  var CELL_H = 22;  // 与表格文字行高一致

  var showItems = bepNormalizeActions(actions);

  // 构建节点列表
  var nodes = showItems.map(function(a) {
    if (a.label === '__more__') {
      var ico = bepIcon('Line/More', 16, BEP_C.primary);
      if (ico) ico.name = 'MoreActions';
      return { node: ico || bepFrame(16, 16, { name:'MoreActions' }), w: 16, h: 16 };
    }
    var color = (a.type === 'danger') ? BEP_C.danger : BEP_C.primary;
    var t = bepText(a.label, color, 14, { lh:22 });
    return { node: t, w: t.width, h: 22 };
  });

  var slotWidths = opts.slotWidths || [];
  var totalW = nodes.reduce(function(sum, n, i) {
    var slotW = slotWidths[i] !== undefined ? slotWidths[i] : n.w;
    return sum + slotW + (i < nodes.length - 1 ? GAP : 0);
  }, 0);

  var wrap = bepFrame(totalW, CELL_H, { name:'ActionCell' });
  var x = 0;
  nodes.forEach(function(n, i) {
    n.node.x = x;
    n.node.y = Math.round((CELL_H - n.h) / 2);
    wrap.appendChild(n.node);
    x += (slotWidths[i] !== undefined ? slotWidths[i] : n.w) + (i < nodes.length - 1 ? GAP : 0);
  });

  return wrap;
}

// ── § 5c 高级表格扩展 ────────────────────────────────────────────────────────

/**
 * 表格单选/多选框（表格 checkbox 列专用，16×16）
 * checked: true|false
 * opts: { disabled, indeterminate }
 */
function bepTableCheckbox(checked, opts) {
  opts = opts || {};
  var disabled = !!opts.disabled;
  var active = checked || opts.indeterminate;
  var box = bepFrame(16, 16, { name:'TableCheckbox/' + (disabled ? 'disabled' : (active ? 'checked' : 'default')), clip:false });
  var bg = bepRect(14, 14, active ? BEP_C.primary : BEP_C.white, { x:1, y:1, r:2 });
  bg.strokes = bepSolid(disabled ? B : (active ? BEP_C.primary : B), disabled ? 0.10 : (active ? 1 : 0.15));
  bg.strokeWeight = 1;
  bg.strokeAlign = 'INSIDE';
  box.appendChild(bg);
  if (checked) {
    var ck = bepIcon('Line/check', 10, BEP_C.white);
    ck.x = 3; ck.y = 3;
    box.appendChild(ck);
  } else if (opts.indeterminate) {
    box.appendChild(bepRect(8, 2, BEP_C.white, { x:4, y:7, r:1 }));
  }
  if (disabled) box.opacity = 0.65;
  return box;
}

/**
 * 表格拖拽柄（可拖拽表格控制列专用）
 */
function bepTableDragHandle() {
  return bepIcon('Line/Drag', 16, bepHex('#BBBBBB'));
}

/**
 * 高级表头行：支持筛选/排序等表头图标。
 * cols: [{label, w, align, iconKey, filter, sort}]
 */
function bepAdvancedTableHeader(cols, tableW, opts) {
  opts = opts || {};
  var spec = bepTableSpec(opts);
  var hdr = bepFrame(tableW, spec.h, { name:'AdvancedTableHeader/' + spec.size, clip:true });
  hdr.fills = bepSolid(B, 0.04);
  hdr.appendChild(bepRect(tableW, 1, B, { a:0.06, x:0, y:spec.bdY }));

  var cx = 0;
  cols.forEach(function(col) {
    var cell = bepFrame(col.w, spec.h, { name:'ATH/' + col.label, clip:true });
    cell.x = cx;
    var iconKey = col.iconKey || (col.filter ? 'Fill/filter' : null);
    var iconSize = iconKey === 'Fill/filter' ? 12 : 16;
    var t = bepText(col.label, B, 14, { style:'Medium', lh:22, a:0.85 });
    var groupW = t.width + (iconKey ? 8 + iconSize : 0);
    var gx = spec.padX;
    if (col.align === 'center') gx = Math.round((col.w - groupW) / 2);
    else if (col.align === 'right') gx = col.w - groupW - spec.padX;
    t.x = gx;
    t.y = spec.headerY;
    cell.appendChild(t);
    if (iconKey) {
      var ico = bepIcon(iconKey, iconSize, col.iconColor || B);
      ico.x = gx + t.width + 8;
      ico.y = Math.round((spec.h - iconSize) / 2);
      cell.appendChild(ico);
    }
    hdr.appendChild(cell);
    cx += col.w;
  });
  return hdr;
}

/**
 * 多级表头（总高80：上层40 + 下层40）。
 * cols: [{label,w,rowSpan:2}|{label,w,children:[{label,w}]}]
 */
function bepMultiLevelTableHeader(cols, tableW) {
  var hdr = bepFrame(tableW, 80, { name:'MultiLevelTableHeader', clip:true });
  hdr.fills = bepSolid(B, 0.04);
  hdr.appendChild(bepRect(tableW, 1, B, { a:0.06, x:0, y:39 }));
  hdr.appendChild(bepRect(tableW, 1, B, { a:0.06, x:0, y:79 }));
  var cx = 0;
  cols.forEach(function(col) {
    if (col.children && col.children.length) {
      var groupW = col.children.reduce(function(sum, child) { return sum + child.w; }, 0);
      var group = bepFrame(groupW, 80, { name:'MTHGroup/' + col.label, clip:true });
      group.x = cx;
      var gt = bepText(col.label, B, 14, { style:'Medium', lh:22, a:0.85 });
      gt.x = Math.round((groupW - gt.width) / 2);
      gt.y = 9;
      group.appendChild(gt);
      var childX = 0;
      col.children.forEach(function(child) {
        var childCell = bepFrame(child.w, 40, { name:'MTHChild/' + child.label, clip:true });
        childCell.x = childX;
        childCell.y = 40;
        var ct = bepText(child.label, B, 14, { style:'Medium', lh:22, a:0.85 });
        ct.x = Math.round((child.w - ct.width) / 2);
        ct.y = 9;
        childCell.appendChild(ct);
        group.appendChild(childCell);
        childX += child.w;
      });
      hdr.appendChild(group);
      cx += groupW;
    } else {
      var cell = bepFrame(col.w, 80, { name:'MTH/' + col.label, clip:true });
      cell.x = cx;
      var t = bepText(col.label, B, 14, { style:'Medium', lh:22, a:0.85 });
      if (col.align === 'right') t.x = col.w - t.width - 16;
      else if (col.align === 'center') t.x = Math.round((col.w - t.width) / 2);
      else t.x = 16;
      t.y = 29;
      cell.appendChild(t);
      hdr.appendChild(cell);
      cx += col.w;
    }
  });
  return hdr;
}

/**
 * 表格行展开详情面板（属于当前表格，不单独做 Card）。
 * items: [{label,value}]
 */
function bepTableExpandPanel(tableW, items, opts) {
  opts = opts || {};
  items = items || [];
  var h = opts.height || 104;
  var panel = bepFrame(tableW, h, { name:'TableExpandPanel', clip:true });
  panel.fills = bepSolid(BEP_C.secondary || bepHex('#F5F7FA'));
  panel.appendChild(bepRect(tableW, 1, B, { a:0.06, x:0, y:h - 1 }));
  var colW = Math.floor((tableW - 32 * 2 - 24 * 2) / 3);
  items.slice(0, 6).forEach(function(item, idx) {
    var col = idx % 3;
    var row = Math.floor(idx / 3);
    var x = 32 + col * (colW + 24);
    var y = 24 + row * 32;
    var label = bepText((item.label || '') + '：', B, 14, { lh:22, a:0.45, x:x, y:y });
    panel.appendChild(label);
    var val = bepTableText(item.value === undefined || item.value === null ? '-' : String(item.value), B, Math.max(40, colW - label.width), { a:0.65 });
    val.x = x + label.width;
    val.y = y;
    panel.appendChild(val);
  });
  return panel;
}

/**
 * 表格快速新增入口行：表头下方首行状态，内部复用 Dashed Button。
 */
function bepQuickAddRow(tableW, opts) {
  opts = opts || {};
  var row = bepFrame(tableW, 48, { name:'QuickAddRow', clip:true });
  row.fills = [];
  row.appendChild(bepRect(tableW, 1, B, { a:0.06, x:0, y:47 }));
  var btn = bepButton(opts.label || '新增一行', 'dashed', 32, { iconKey:'Line/Add', width:tableW - 32 });
  btn.x = 16;
  btn.y = 8;
  row.appendChild(btn);
  return row;
}

// ── § 5c 树表格行 ────────────────────────────────────────────────────────────

/**
 * 树表格行（BeP唯一树状表格规范：层级缩进 + 展开/折叠图标 + 子级底色）
 *
 * cells  : [{content, align}]  同 bepTableRow
 * cols   : [{label, w, align}] 同 bepTableRow
 * tableW : 总宽
 * level  : 层级，0=根节点，1=一级子节点，以此类推
 * state  : 'expanded'（已展开）| 'collapsed'（已折叠）| 'leaf'（叶子节点，无子项）
 * bgColor: 可选背景色覆盖（不传时按层级：一级白底，子级#F5F7FA）
 * opts  : {treeCol:0} 树状层级所在列；有checkbox列时传 {treeCol:1}
 *
 * 规则：
 *   · 每级缩进 16px
 *   · 展开/折叠图标 16×16，图标与文字间距 8px，叶子节点保留占位宽度使文字对齐
 *   · 一级行白底，二级/三级等子级行使用 #F5F7FA，整行贯通
 */
function bepTreeRow(cells, cols, tableW, level, state, bgColor, opts) {
  level = level || 0;
  state = state || 'leaf';
  opts = opts || {};

  var INDENT   = 16;   // 每级缩进宽度
  var ICON_SZ  = 16;   // 展开/折叠图标尺寸（Figma真源）
  var ICON_GAP = 8;    // 图标与文字间距
  var ROW_H    = 48;
  var TREE_COL = opts.treeCol !== undefined ? opts.treeCol : 0;

  var row = bepFrame(tableW, ROW_H, { name:'TreeRow·L' + level, clip:true });

  // 背景色
  if (bgColor !== undefined && bgColor !== null) {
    row.fills = bepSolid(bgColor);
  } else if (level > 0) {
    row.fills = bepSolid(BEP_C.secondary || bepHex('F5F7FA'));
  } else {
    row.fills = [];
  }

  // 底边框
  row.appendChild(bepRect(tableW, 1, B, { a:0.06, x:0, y:ROW_H - 1 }));

  var cx = 0;
  cells.forEach(function(cell, i) {
    var col       = cols[i] || { w:100, align:'left' };
    var cellFrame = bepFrame(col.w, ROW_H, { name:'TD' + i });
    cellFrame.x   = cx;

    var content = cell.content !== undefined ? cell.content : cell;
    var align   = cell.align || col.align || 'left';

    if (i === TREE_COL) {
      // 树状列：缩进 + 图标（或占位）+ 文字
      var indentX = 16 + level * INDENT;
      var textX   = indentX + ICON_SZ + ICON_GAP;  // 文字起始 X（含图标占位）

      if (state === 'expanded' || state === 'collapsed') {
        // 有子节点：显示展开/折叠箭头
        var icoKey = (state === 'expanded') ? 'Fill/Arrow-Open' : 'Fill/Arrow-PutAway';
        var ico = bepIcon(icoKey, ICON_SZ, bepHex('666666'));
        if (ico) {
          ico.x = indentX;
          ico.y = Math.round((ROW_H - ICON_SZ) / 2);
          cellFrame.appendChild(ico);
        }
      }
      // 叶子节点：不放图标，但 textX 保持相同偏移（文字与有图标行对齐）

      var node;
      if (typeof content === 'string') {
        node = bepTableText(content, B, Math.max(24, col.w - textX - 16), { lh:22, a:0.65 });
      } else {
        node = content;
      }
      node.x = textX;
      node.y = Math.round((ROW_H - (node.height || 22)) / 2);
      cellFrame.appendChild(node);

    } else {
      // 其他列：与 bepTableRow 完全相同
      var node2;
      if (typeof content === 'string') {
        node2 = bepTableText(content, B, col.w - 32, { lh:22, a:0.65 });
      } else {
        node2 = content;
      }
      node2.y = Math.round((ROW_H - (node2.height || 22)) / 2);
      if      (align === 'center') node2.x = Math.round((col.w - (node2.width || 60)) / 2);
      else if (align === 'right')  node2.x = col.w - (node2.width || 60) - 16;
      else                         node2.x = 16;
      cellFrame.appendChild(node2);
    }

    row.appendChild(cellFrame);
    cx += col.w;
  });

  return row;
}

// ── § 6  分页器（Figma实测：高32px，页码32×32，cornerRadius=2）─────────────

/**
 * total: 总条数文字（如 '共300条'）；current: 当前页码（数字）
 * pages: 要显示的页码数组，如 [1,2,3,'…',20]
 * pageSize: 每页条数文字（默认 '10条/页'）
 * opts: { showPageSize, showJump, pageSizeWidth, jumpWidth, disabledPrev, disabledNext }
 *
 * 结构：共N条  <  1 2 3 … 50  >  [10条/页 ∨]  跳转至 [__] 页
 */
function bepPagination(totalText, current, pages, pageSize, opts) {
  if (typeof pageSize === 'object' && pageSize !== null) {
    opts = pageSize;
    pageSize = undefined;
  }
  opts = opts || {};
  current  = current  || 1;
  pages    = pages    || [1, 2, 3, '…', 20];
  pageSize = pageSize || '10条/页';
  var wrap = bepFrame(0, 32, { name:'Pagination' });
  var cx   = 0;

  // 总条数文字
  if (totalText) {
    var tot = bepText(totalText, B, 14, { lh:22, a:0.65 });
    tot.y = 5; tot.x = cx;
    wrap.appendChild(tot);
    cx += tot.width + 8;
  }

  // 左翻箭头
  var prevBox = bepFrame(32, 32, { name:'Prev', clip:true });
  prevBox.fills        = bepSolid(BEP_C.white);
  prevBox.cornerRadius = 2;
  prevBox.strokes      = bepSolid(B, 0.15);
  prevBox.strokeWeight = 1;
  prevBox.strokeAlign  = 'INSIDE';
  if (opts.disabledPrev) prevBox.opacity = 0.5;
  var leftIco = bepIcon('Line/chevron-left', 16, B);
  if (leftIco) { leftIco.x = 8; leftIco.y = 8; leftIco.opacity = opts.disabledPrev ? 0.25 : 0.65; prevBox.appendChild(leftIco); }
  prevBox.x = cx; cx += 32 + 8;
  wrap.appendChild(prevBox);

  // 页码
  pages.forEach(function(p) {
    var isActive = (p === current);
    var pageBox  = bepFrame(32, 32, { name:'Page/' + p, clip:true });
    pageBox.cornerRadius = 2;
    if (isActive) {
      pageBox.fills = bepSolid(BEP_C.primary);
      var pt = bepText(String(p), BEP_C.white, 14, { lh:22 });
      pt.x = Math.round((32 - pt.width) / 2); pt.y = 5;
      pageBox.appendChild(pt);
    } else if (p === '…') {
      pageBox.fills   = bepSolid(BEP_C.white);
      pageBox.strokes = bepSolid(B, 0.15); pageBox.strokeWeight = 1; pageBox.strokeAlign = 'INSIDE';
      var et = bepText('…', B, 14, { lh:22, a:0.85 });
      et.x = Math.round((32 - et.width) / 2); et.y = 5;
      pageBox.appendChild(et);
    } else {
      pageBox.fills   = bepSolid(BEP_C.white);
      pageBox.strokes = bepSolid(B, 0.15); pageBox.strokeWeight = 1; pageBox.strokeAlign = 'INSIDE';
      var nt = bepText(String(p), B, 14, { lh:22, a:0.85 });
      nt.x = Math.round((32 - nt.width) / 2); nt.y = 5;
      pageBox.appendChild(nt);
    }
    pageBox.x = cx; cx += 32 + 8;
    wrap.appendChild(pageBox);
  });

  // 右翻箭头
  var nextBox = bepFrame(32, 32, { name:'Next', clip:true });
  nextBox.fills        = bepSolid(BEP_C.white);
  nextBox.cornerRadius = 2;
  nextBox.strokes      = bepSolid(B, 0.15);
  nextBox.strokeWeight = 1;
  nextBox.strokeAlign  = 'INSIDE';
  if (opts.disabledNext) nextBox.opacity = 0.5;
  var rightIco = bepIcon('Line/chevron-right', 16, B);
  if (rightIco) { rightIco.x = 8; rightIco.y = 8; rightIco.opacity = opts.disabledNext ? 0.25 : 0.65; nextBox.appendChild(rightIco); }
  nextBox.x = cx; cx += 32 + 8;
  wrap.appendChild(nextBox);

  // 每页条数选择器（bepSelect，宽度按文字自适应）
  if (opts.showPageSize !== false) {
    var pageSizeW = opts.pageSizeWidth || 96;
    var psSelect = bepSelect(pageSize, pageSizeW, 32, { value:pageSize });
    psSelect.x = cx; cx += pageSizeW + 8;
    wrap.appendChild(psSelect);
  }

  // 跳转至
  if (opts.showJump !== false) {
    var jumpLbl = bepText('跳转至', B, 14, { lh:22, a:0.65 });
    jumpLbl.x = cx; jumpLbl.y = 5;
    wrap.appendChild(jumpLbl);
    cx += jumpLbl.width + 8;

    // 页码输入框（小型，48px 宽）
    var jumpW = opts.jumpWidth || 48;
    var jumpInput = bepInput('', jumpW, 32, { value:opts.jumpValue || '' });
    jumpInput.x = cx; cx += jumpW + 8;
    wrap.appendChild(jumpInput);

    // 页
    var pageLbl = bepText('页', B, 14, { lh:22, a:0.65 });
    pageLbl.x = cx; pageLbl.y = 5;
    wrap.appendChild(pageLbl);
    cx += pageLbl.width;
  }

  wrap.resize(cx, 32);
  return wrap;
}

// ── § 6b 弹窗 Modal ──────────────────────────────────────────────────────────

/**
 * 提醒弹窗 / 对话框 POP（轻量确认）
 *
 * Figma 真源：BeP Admin Kit Sketch V1.1.0 1 / 704:28546 / 对话框 POP
 *
 * title   : 标题，如 删除数据 / 禁用数据 / 退出编辑
 * message : 提醒内容
 * opts : {
 *   type         : 'danger'|'warning'|'info'（默认 info）
 *   width        : 默认 420；提醒弹窗标准宽度为 420
 *   confirmLabel : 确认按钮文案（默认 '确 定'）
 *   cancelLabel  : 取消按钮文案（默认 '取 消'）
 *   showCancel   : 是否显示取消按钮（默认 true；普通提示可设 false）
 *   showClose    : 是否显示右上关闭（默认 true）
 *   overlay      : 是否返回遮罩 + 弹窗（默认 true；样例展示可设 false）
 *   canvasW      : 遮罩宽度（默认 1440）
 *   canvasH      : 遮罩高度（默认 900）
 * }
 */
function bepAlertModal(title, message, opts) {
  opts = opts || {};
  var type = opts.type || 'info';
  var width = opts.width || 420;
  var canvasW = opts.canvasW || 1440;
  var canvasH = opts.canvasH || 900;
  var showCancel = opts.showCancel !== false;
  var showClose = opts.showClose !== false;
  var overlay = opts.overlay !== false;

  var cfgMap = {
    danger:  { icon:'Fill/Fail',     color:BEP_C.danger,  confirmType:'danger' },
    warning: { icon:'Fill/Abnormal', color:BEP_C.warning, confirmType:'primary' },
    info:    { icon:'Fill/Tips',     color:BEP_C.primary, confirmType:'primary' }
  };
  var cfg = cfgMap[type] || cfgMap.info;

  var PAD_X = 40;
  var TOP = 40;
  var ICON = 24;
  var GAP = 16;
  var TITLE_LH = 24;
  var BODY_LH = 22;
  var BTN_H = 32;
  var BTN_GAP = 8;
  var textX = PAD_X + ICON + GAP;
  var textW = width - textX - PAD_X;
  var messageText = message === undefined || message === null ? '' : String(message);
  var approxCharsPerLine = Math.max(10, Math.floor(textW / 14));
  var bodyLines = Math.max(1, Math.ceil(messageText.length / approxCharsPerLine));
  var bodyH = bodyLines * BODY_LH;
  var bodyY = TOP + TITLE_LH + 16;
  var buttonsY = bodyY + bodyH + 32;
  var panelH = Math.max(170, buttonsY + BTN_H + 36);

  var panel = bepFrame(width, panelH, { name:'AlertModal/' + type, r:2, clip:true });
  panel.fills = bepSolid(BEP_C.white);
  panel.effects = [
    { type:'DROP_SHADOW', color:{ r:0, g:0, b:0, a:0.05 }, offset:{ x:0, y:9 }, radius:28, spread:8, visible:true, blendMode:'NORMAL' },
    { type:'DROP_SHADOW', color:{ r:0, g:0, b:0, a:0.08 }, offset:{ x:0, y:6 }, radius:16, spread:0, visible:true, blendMode:'NORMAL' },
    { type:'DROP_SHADOW', color:{ r:0, g:0, b:0, a:0.12 }, offset:{ x:0, y:3 }, radius:6,  spread:-4, visible:true, blendMode:'NORMAL' }
  ];

  var icon = bepIcon(cfg.icon, ICON, cfg.color);
  icon.x = PAD_X;
  icon.y = TOP;
  panel.appendChild(icon);

  var titleText = bepText(title || '标题', B, 16, { style:'Medium', lh:TITLE_LH, a:0.85 });
  titleText.x = textX;
  titleText.y = TOP;
  panel.appendChild(titleText);

  var body = figma.createText();
  body.fontName = { family:'PingFang SC', style:'Regular' };
  body.fontSize = 14;
  body.lineHeight = { value:BODY_LH, unit:'PIXELS' };
  body.characters = messageText;
  body.fills = bepSolid(B, 0.65);
  body.textAutoResize = 'NONE';
  body.textTruncation = 'DISABLED';
  body.resize(textW, bodyH);
  body.x = textX;
  body.y = bodyY;
  panel.appendChild(body);

  if (showClose) {
    var closeIco = bepIcon('Line/Close', 16, BEP_C.primary);
    closeIco.x = width - PAD_X - 16;
    closeIco.y = 32;
    panel.appendChild(closeIco);
  }

  var confirmLabel = opts.confirmLabel || '确 定';
  var cancelLabel = opts.cancelLabel || '取 消';
  var confirmBtn = bepButton(confirmLabel, cfg.confirmType, BTN_H);
  var cancelBtn = showCancel ? bepButton(cancelLabel, 'secondary', BTN_H) : null;
  var buttonsW = confirmBtn.width + (cancelBtn ? BTN_GAP + cancelBtn.width : 0);
  var buttonsX = width - PAD_X - buttonsW;
  if (cancelBtn) {
    cancelBtn.x = buttonsX;
    cancelBtn.y = buttonsY;
    panel.appendChild(cancelBtn);
    confirmBtn.x = buttonsX + cancelBtn.width + BTN_GAP;
  } else {
    confirmBtn.x = buttonsX;
  }
  confirmBtn.y = buttonsY;
  panel.appendChild(confirmBtn);

  if (!overlay) return panel;

  var mask = bepFrame(canvasW, canvasH, { name:'AlertModal/Overlay' });
  mask.fills = bepSolid(B, 0.45);
  panel.x = Math.round((canvasW - width) / 2);
  panel.y = Math.round((canvasH - panelH) / 2);
  mask.appendChild(panel);
  return mask;
}

/**
 * BeP 标准弹窗（遮罩 + 弹窗）
 *
 * title       : 弹窗标题字符串
 * contentNode : 内容区节点（由调用方创建并传入），传 null 则内容区留空 100px
 * opts : {
 *   width        : 弹窗宽度（默认 640）
 *                  规格：420（小/简单确认）/ 640（中/默认）/ 800（大/复杂表单）
 *   confirmLabel : 确认按钮文案（默认 '确 定'）
 *   cancelLabel  : 取消按钮文案（默认 '取 消'）
 *   variant      : 'form'|'detail'（默认 form；detail 默认不显示底部按钮）
 *   showFooter   : 是否显示底部按钮区（form 默认 true，detail 默认 false；显式传值优先）
 *   canvasW      : 遮罩宽度（默认 1440）
 *   canvasH      : 遮罩高度（默认 900）
 * }
 *
 * 垂直定位规则（Figma实测）：
 *   高度 ≤ 630px → 垂直居中
 *   高度 > 630px → 距顶部 15%（canvasH × 0.15 = 135px）
 *
 * 结构：
 *   遮罩 rgba(0,0,0,0.45)
 *   └── 弹窗（白色，cornerRadius=2）
 *       ├── 标题栏 56px（标题左对齐 + × 图标右对齐）
 *       ├── 标题栏底部分隔线 1px（包含在 56px 内）
 *       ├── 内容区（上下左右 24px padding，内容起点 y=80）
 *       ├── 底部分隔线 1px（showFooter=true 时，包含在底部操作区内）
 *       └── 底部按钮 52px（取消在左，确定在右，右对齐）
 */
function bepModal(title, contentNode, opts) {
  opts         = opts         || {};
  var width    = opts.width        || 640;
  var confLbl  = opts.confirmLabel || '确 定';
  var canlLbl  = opts.cancelLabel  || '取 消';
  var variant  = opts.variant || 'form';
  var showFoot = opts.showFooter !== undefined ? opts.showFooter : variant !== 'detail';
  var canvasW  = opts.canvasW      || 1440;
  var canvasH  = opts.canvasH      || 900;

  var TITLE_H = 56;
  var DIV_H   = 1;
  var PAD     = 24;
  var FOOT_H  = 52;
  var BTN_H   = 32;
  var BTN_GAP = 8;

  var contentH = (contentNode && contentNode.height) ? contentNode.height : 100;

  // 计算弹窗总高度
  var modalH = TITLE_H + PAD + contentH + PAD
             + (showFoot ? FOOT_H : 0);

  // ── 遮罩 ──
  var mask = bepFrame(canvasW, canvasH, { name:'Modal/Overlay' });
  mask.fills = bepSolid(B, 0.45);

  // ── 弹窗主体 ──
  var modal = bepFrame(width, modalH, { name:'Modal', r:2, clip:true });
  modal.fills = bepSolid(BEP_C.white);
  modal.x = Math.round((canvasW - width) / 2);
  // 垂直位置：高度>630px时距顶15%，否则垂直居中
  modal.y = (modalH > canvasH * 0.70)
    ? Math.round(canvasH * 0.15)
    : Math.round((canvasH - modalH) / 2);

  // 标题栏
  var titleBar = bepFrame(width, TITLE_H, { name:'ModalTitle' });
  titleBar.fills = [];
  var titleTxt = bepText(title || '标题', B, 16, { style:'Medium', lh:24, a:0.85 });
  titleTxt.x = PAD; titleTxt.y = Math.round((TITLE_H - 24) / 2);
  titleBar.appendChild(titleTxt);

  var closeIco = bepIcon('Line/Close', 16, B);
  if (closeIco) {
    closeIco.opacity = 0.45;
    closeIco.x = width - PAD - 16;
    closeIco.y = Math.round((TITLE_H - 16) / 2);
    titleBar.appendChild(closeIco);
  }
  modal.appendChild(titleBar);

  // 标题下分隔线（包含在标题栏56px内，y=55）
  modal.appendChild(bepRect(width, DIV_H, B, { a:0.10, x:0, y:TITLE_H - 1 }));
  var y = TITLE_H;

  // 内容区
  y += PAD;
  if (contentNode) {
    contentNode.x = PAD;
    contentNode.y = y;
    modal.appendChild(contentNode);
  }
  y += contentH + PAD;

  // 底部
  if (showFoot) {
    var footer = bepFrame(width, FOOT_H, { name:'ModalFooter' });
    footer.fills = []; footer.y = y;
    footer.appendChild(bepRect(width, DIV_H, B, { a:0.10, x:0, y:0 }));

    var canlBtn = bepButton(canlLbl, 'secondary', BTN_H);
    var confBtn = bepButton(confLbl, 'primary',   BTN_H);

    // 右对齐，取消在左，确定在右
    var totalW = canlBtn.width + BTN_GAP + confBtn.width;
    var bx     = width - PAD - totalW;
    var by     = Math.round((FOOT_H - BTN_H) / 2);
    canlBtn.x = bx;                        canlBtn.y = by;
    confBtn.x = bx + canlBtn.width + BTN_GAP; confBtn.y = by;

    footer.appendChild(canlBtn);
    footer.appendChild(confBtn);
    modal.appendChild(footer);
  }

  mask.appendChild(modal);
  return mask;
}

// ── § 6c 表单项 ──────────────────────────────────────────────────────────────

/**
 * BeP 标准表单项（Label + 控件，支持必填和错误态）
 *
 * label    : 字段名称字符串
 * ctrlNode : 已创建好的控件节点（bepInput / bepSelect / bepDateRange 等）
 * opts: {
 *   labelW   : 标签区固定宽度（同一表单所有项必须传相同值，默认 112）
 *   required : true | false（默认 false）显示红色 * 号
 *   error    : null | '错误提示文字'（有值时控件显示红色边框 + 下方红色提示）
 *   gap      : 标签与控件间距（默认 12）
 * }
 *
 * 高度：
 *   正常态：32px（控件高）
 *   错误态：32px + 4px + 20px（提示文字）= 56px
 *
 * 标签规则：
 *   · 固定 labelW 宽度，文字右对齐
 *   · 必填时在标签左侧显示红色 *（间距 4px）
 *   · 标签与控件垂直居中对齐
 *
 * 典型用法（同一表单统一 labelW）：
 *   bepFormItem('用户名', bepInput('请输入', 300, 32), { labelW:112, required:true })
 *   bepFormItem('状态',   bepSelect('请选择', 300, 32), { labelW:112 })
 *   bepFormItem('手机号', bepInput('请输入', 300, 32), { labelW:112, error:'请输入正确的手机号' })
 */
function bepFormItem(label, ctrlNode, opts) {
  opts     = opts     || {};
  var LBL_W    = opts.labelW  || 112;
  var GAP      = opts.gap     || 12;
  var required = opts.required || false;
  var error    = opts.error    || null;

  var CTRL_H   = ctrlNode ? (ctrlNode.height || 32) : 32;
  var ERR_GAP  = 0;
  var ERR_H    = 20;   // 错误文字行高
  var STAR_GAP = 4;    // * 与标签文字间距

  // 行高固定 = CTRL_H（32px），FIELD_GAP 保持 20px 不变
  // 错误文字浮于 gap 区域内，clip:false 保证可见
  var totalH = CTRL_H;
  var ctrlW  = ctrlNode ? (ctrlNode.width || 200) : 200;
  var totalW = LBL_W + GAP + ctrlW;

  var wrap = bepFrame(totalW, totalH, { name:'FormItem/' + label, clip: false });

  // ── 必填星号 ──
  if (required) {
    var star = bepText('*', bepHex('FE5E54'), 14, { lh:22 });
    // 星号右边缘对齐 (LBL_W - STAR_GAP - labelText.width)，先放在标签左侧
    star.x = 0;
    star.y = Math.round((CTRL_H - 22) / 2);
    wrap.appendChild(star);
  }

  // ── 标签文字（右对齐到 LBL_W）──
  var lbl = bepText(label || '', B, 14, { lh:22, a:0.85 });
  lbl.x   = LBL_W - lbl.width;
  lbl.y   = Math.round((CTRL_H - 22) / 2);
  wrap.appendChild(lbl);

  // 必填 * 重新定位到标签文字左侧（间距4px）
  if (required) {
    var s = wrap.children[0];  // 刚才追加的 star
    s.x = lbl.x - STAR_GAP - s.width;
  }

  // ── 控件 ──
  if (ctrlNode) {
    ctrlNode.x = LBL_W + GAP;
    ctrlNode.y = 0;

    // 错误态：红色边框覆盖控件
    if (error) {
      ctrlNode.strokes     = bepSolid(bepHex('FE5E54'), 1);
      ctrlNode.strokeWeight = 1;
      ctrlNode.strokeAlign  = 'INSIDE';
    }

    wrap.appendChild(ctrlNode);
  }

  // ── 错误提示文字 ──
  if (error) {
    var errTxt = bepText(error, bepHex('FE5E54'), 12, { lh:20 });
    errTxt.x = LBL_W + GAP;
    errTxt.y = CTRL_H + ERR_GAP;
    wrap.appendChild(errTxt);
  }

  return wrap;
}

// ── § 6d 抽屉 Drawer ─────────────────────────────────────────────────────────

/**
 * BeP 标准抽屉（从右侧滑入，高度填满画布）
 *
 * title       : 抽屉标题字符串
 * contentNode : 内容区节点（由调用方创建并传入），传 null 则留空
 * opts : {
 *   width        : 抽屉宽度（默认 640，中等；大 800，小 420）
 *   variant      : 'form' | 'detail'；form 默认有底部按钮，detail 默认无底部按钮
 *   confirmLabel : 确认按钮文案（默认 '确 定'）
 *   cancelLabel  : 取消按钮文案（默认 '取 消'）
 *   showFooter   : 是否显示底部按钮区；显式传值优先于 variant 默认值
 *   canvasW      : 画布宽度（默认 1440）
 *   canvasH      : 画布高度（默认 900）
 * }
 *
 * 结构：
 *   完整遮罩 rgba(0,0,0,0.45)
 *   └── 抽屉面板（白色，右侧，高度=canvasH）
 *       ├── 标题栏 56px（标题左对齐 + × 图标右对齐，底部分割线在标题栏内）
 *       ├── 内容区（上下左右 24px padding，长内容表现为内容区滚动）
 *       └── 底部按钮 52px（可选；取消在左，确定在右，右对齐，间距 8px）
 */
function bepDrawer(title, contentNode, opts) {
  opts        = opts        || {};
  var width   = opts.width        || 640;
  var variant = opts.variant      || 'form';
  var confLbl = opts.confirmLabel || '确 定';
  var canlLbl = opts.cancelLabel  || '取 消';
  var showFoot = (opts.showFooter !== undefined) ? opts.showFooter : (variant !== 'detail');
  var canvasW  = opts.canvasW    || 1440;
  var canvasH  = opts.canvasH    || 900;

  var TITLE_H = 56;
  var DIV_H   = 1;
  var PAD     = 24;
  var FOOT_H  = 52;
  var BTN_H   = 32;
  var BTN_GAP = 8;
  var FOOTER_RIGHT = 16;

  var overlay = bepFrame(canvasW, canvasH, { name:'Drawer/Overlay', clip:true });
  overlay.fills = bepSolid(B, 0.45);

  // 抽屉面板
  var panel = bepFrame(width, canvasH, { name:'Drawer', clip:true });
  panel.fills = bepSolid(BEP_C.white);
  panel.x = canvasW - width;
  panel.y = 0;
  panel.effects = [
    { type:'DROP_SHADOW', color:{ r:0, g:0, b:0, a:0.05 }, offset:{ x:0, y:9 }, radius:28, spread:8, visible:true, blendMode:'NORMAL' },
    { type:'DROP_SHADOW', color:{ r:0, g:0, b:0, a:0.08 }, offset:{ x:0, y:6 }, radius:16, spread:0, visible:true, blendMode:'NORMAL' },
    { type:'DROP_SHADOW', color:{ r:0, g:0, b:0, a:0.12 }, offset:{ x:0, y:3 }, radius:6, spread:-4, visible:true, blendMode:'NORMAL' }
  ];

  // 标题栏
  var titleBar = bepFrame(width, TITLE_H, { name:'DrawerTitle' });
  titleBar.fills = [];
  var titleTxt = bepText(title || '标题', B, 16, { style:'Medium', lh:24, a:0.85 });
  titleTxt.x = PAD; titleTxt.y = Math.round((TITLE_H - 24) / 2);
  titleBar.appendChild(titleTxt);
  var closeIco = bepIcon('Line/Close', 16, B);
  if (closeIco) {
    closeIco.opacity = 1;
    closeIco.fills = bepSolid(BEP_C.primary);
    closeIco.x = width - PAD - 16;
    closeIco.y = Math.round((TITLE_H - 16) / 2);
    titleBar.appendChild(closeIco);
  }
  titleBar.appendChild(bepRect(width, DIV_H, B, { a:0.10, x:0, y:TITLE_H - DIV_H }));
  panel.appendChild(titleBar);

  // 内容区
  var y = TITLE_H + PAD;
  if (contentNode) {
    contentNode.x = PAD;
    contentNode.y = y;
    panel.appendChild(contentNode);
  }
  // 底部固定在抽屉底端；内容高度不足时不能跟随内容上移。
  if (showFoot) {
    var footer = bepFrame(width, FOOT_H, { name:'DrawerFooter' });
    footer.fills = [];
    footer.y = canvasH - FOOT_H;
    footer.appendChild(bepRect(width, DIV_H, B, { a:0.10, x:0, y:0 }));

    var canlBtn = bepButton(canlLbl, 'secondary', BTN_H);
    var confBtn = bepButton(confLbl, 'primary',   BTN_H);
    var totalW  = canlBtn.width + BTN_GAP + confBtn.width;
    var bx      = width - FOOTER_RIGHT - totalW;
    var by      = Math.round((FOOT_H - BTN_H) / 2);
    canlBtn.x = bx;                            canlBtn.y = by;
    confBtn.x = bx + canlBtn.width + BTN_GAP;  confBtn.y = by;
    footer.appendChild(canlBtn);
    footer.appendChild(confBtn);
    panel.appendChild(footer);
  }

  overlay.appendChild(panel);
  return overlay;
}

// ── § 7  页头 Header（SKILL.md: 总高96px = TopBar48 + TitleBar48）──────────

/**
 * 第一行：TopBar（48px 白色）
 * 左侧：MenuOpen图标 + 业务系统切换输入框
 * 右侧：Search / Download / Notice 图标 + 分隔线 + 头像 + 用户名
 */
function bepTopBar(totalWidth) {
  totalWidth = totalWidth || 1440;
  var bar = bepFrame(totalWidth, 48, { name:'TopBar', clip:true });
  bar.fills = bepSolid(BEP_C.white);
  bar.appendChild(bepRect(totalWidth, 1, B, { a:0.06, x:0, y:47 }));

  // 左侧：菜单折叠图标
  var menuIco = bepIcon('Fill/MenuOpen', 16, bepHex('666666'));
  menuIco.x = 24; menuIco.y = 16;
  bar.appendChild(menuIco);

  // 左侧：系统切换选择框（bepSelect 基础上将 DropDown-Arrow 换为 Line/Switch）
  var sysInput = bepSelect('业务系统切换', 200, 32);
  // 移除 bepSelect 默认追加的下拉箭头，换为切换图标
  var lastChild = sysInput.children[sysInput.children.length - 1];
  if (lastChild) lastChild.remove();
  // 系统切换是已选值，不是 placeholder；文字使用正文 85%。
  var sysText = sysInput.findOne(function(n) { return n.type === 'TEXT'; });
  if (sysText) sysText.fills = bepSolid(B, 0.85);
  var switchIco = bepIcon('Line/Switch', 16, B);
  if (switchIco) { switchIco.x = 200 - 16 - 12; switchIco.y = 8; switchIco.opacity = 0.45; sysInput.appendChild(switchIco); }
  sysInput.x = 64; sysInput.y = 8;  // ≡右边缘(40) + 24px gap = 64
  bar.appendChild(sysInput);

  // 右侧图标组（右对齐，距右24px，y=16）
  var rightX = totalWidth - 24;
  // 用户名 + 下拉箭头
  var userName = bepText('管理员', B, 14, { lh:22, a:0.85 });
  var arrowIco = bepIcon('Fill/Arrow-Open', 16, B);
  if (arrowIco) { arrowIco.opacity = 0.65; }
  // 头像圆形
  var avatar = bepRect(24, 24, BEP_C.primary, { r:12 });
  var avatarTxt = bepText('A', BEP_C.white, 12, { lh:18 });
  avatarTxt.x = Math.round((24 - avatarTxt.width) / 2);
  avatarTxt.y = Math.round((24 - 18) / 2);
  var avatarG = bepFrame(24, 24, { name:'Avatar', clip:true });
  avatarG.fills = []; avatarG.appendChild(avatar); avatarG.appendChild(avatarTxt);

  // 右侧布局（从右向左）
  if (arrowIco) { rightX -= arrowIco.width; arrowIco.x = rightX; arrowIco.y = 16; bar.appendChild(arrowIco); }
  rightX -= (userName.width + 4);  // 用户名→▼ gap: 4px
  userName.x = rightX; userName.y = 13; bar.appendChild(userName);
  rightX -= (24 + 8);
  avatarG.x = rightX; avatarG.y = 12; bar.appendChild(avatarG);
  // 分隔线
  rightX -= (1 + 16);
  var sep = bepRect(1, 16, B, { a:0.10, x:rightX, y:16 });
  bar.appendChild(sep);
  rightX -= 32;  // 🔔图标16px + 右侧16px gap到分隔线（间距16px ✓）
  // Notice
  var noticeIco = bepIcon('Line/bell', 16, bepHex('666666'));  // Feather 铃铛，无mask
  if (noticeIco) { noticeIco.x = rightX; noticeIco.y = 16; bar.appendChild(noticeIco); }
  rightX -= 40;
  var dlIco = bepIcon('Line/download', 16, bepHex('666666'));  // Feather 下载
  if (dlIco) { dlIco.x = rightX; dlIco.y = 16; bar.appendChild(dlIco); }
  rightX -= 40;
  var searchIco = bepIcon('Line/search', 16, bepHex('666666'));  // Feather 搜索
  if (searchIco) { searchIco.x = rightX; searchIco.y = 16; bar.appendChild(searchIco); }

  return bar;
}

/**
 * 第二行：TitleBar（48px，带底边框 1px rgba(0,0,0,0.10)）
 * title: 页面标题；breadcrumbs: 面包屑数组；totalWidth: 宽度
 * opts.rightActions: [{label, type}] 右侧操作按钮（可选）
 */
function bepTitleBar(title, breadcrumbs, totalWidth, opts) {
  opts = opts || {};
  totalWidth = totalWidth || 1440;
  var bar = bepFrame(totalWidth, 48, { name:'TitleBar', clip:true });
  bar.fills = bepSolid(BEP_C.white);
  bar.appendChild(bepRect(totalWidth, 1, B, { a:0.10, x:0, y:47 }));

  // 标题
  var titleNode = bepText(title, B, 16, { style:'Medium', lh:24, a:0.85 });
  titleNode.x = 24; titleNode.y = 12;
  bar.appendChild(titleNode);

  // 面包屑
  var crumbs = breadcrumbs || [];
  var bx = titleNode.x + titleNode.width + 16;
  crumbs.forEach(function(item, idx) {
    var ct = bepText(item, B, 14, { lh:22, a:0.65 });
    ct.x = bx; ct.y = 13;
    bar.appendChild(ct);
    bx += ct.width + 5;
    if (idx < crumbs.length - 1) {
      var arrIco = bepIcon('Line/Right-Arrow', 12, bepHex('666666'));
      if (arrIco) { arrIco.x = bx; arrIco.y = 18; bar.appendChild(arrIco); bx += 12 + 6; }
      else { bx += 18; }
    }
  });

  // 右侧操作按钮（可选，右对齐，间距8px）
  if (opts.rightActions && opts.rightActions.length > 0) {
    var rx = totalWidth - 24;
    opts.rightActions.slice().reverse().forEach(function(a) {
      var btn = bepButton(a.label, a.type || 'secondary', 32);
      rx -= btn.width;
      btn.x = rx; btn.y = 8;
      bar.appendChild(btn);
      rx -= 8;
    });
  }

  return bar;
}

// ── § 7c 页签 Tabs（替代 TitleBar，置于 TopBar 下方）────────────────────────

/**
 * 页签导航栏（替代 TitleBar，高48px）
 * tabs     : 标签文字数组，如 ['选项一','选项二','选项三']
 * activeIdx: 当前选中的标签索引（默认0）
 * totalWidth: 总宽（默认 CANVAS_W - SIDE_W = 1232）
 *
 * 结构（Figma 实测 node 0:1459）：
 *   容器：h=48，背景 #F0F2F5
 *   左右翻页按钮：32×32，x=16 / right=16，白底 r=4，0 0 2 rgba(0,0,0,0.10)
 *   标签区：x=52，gap=4，y=8；标签宽度由文字 + close 反推
 *   标签：h=32，白底 r=4，padding 16px，文字与 close gap=4
 *   默认态：文字 rgba(0,0,0,0.65)，close rgba(0,0,0,0.45)
 *   选中态：文字 #006D9B，close #006D9B；无下划线
 *   Hover 态：文字 #338AAF，close #006D9B（页面生成时可用 opts.hoverIdx 指定）
 */
function bepTabs(tabs, activeIdx, totalWidth, opts) {
  tabs      = tabs      || [];
  activeIdx = (activeIdx !== undefined) ? activeIdx : 0;
  totalWidth = totalWidth || 1232;
  opts = opts || {};
  var hoverIdx = opts.hoverIdx;

  var bar = bepFrame(totalWidth, 48, { name:'Tabs', clip:true });
  bar.fills = bepSolid(BEP_C.pageBg);

  function navBtn(dir) {
    var btn = bepFrame(32, 32, { name:'TabsNav/' + dir, r:4, clip:true });
    btn.fills = bepSolid(BEP_C.white);
    btn.effects = [{
      type:'DROP_SHADOW',
      color:{ r:0, g:0, b:0, a:0.10 },
      offset:{ x:0, y:0 },
      radius:2,
      spread:0,
      visible:true,
      blendMode:'NORMAL',
    }];
    var ico = bepIcon(dir === 'left' ? 'Line/Left-Arrow' : 'Line/Right-Arrow', 12, B);
    if (ico) {
      ico.opacity = 0.45;
      ico.x = 10;
      ico.y = 10;
      btn.appendChild(ico);
    }
    return btn;
  }

  var TAB_H = 32, TAB_GAP = 4, TAB_X = 52, TAB_Y = 8;
  var cx = TAB_X;
  tabs.forEach(function(label, i) {
    var isActive = (i === activeIdx);
    var isHover = (i === hoverIdx);
    var txtColor = isActive ? BEP_C.primary : (isHover ? bepHex('338AAF') : B);
    var txtOpacity = (isActive || isHover) ? 1 : 0.65;
    var closeColor = (isActive || isHover) ? BEP_C.primary : B;
    var closeOpacity = (isActive || isHover) ? 1 : 0.45;
    var t = bepText(label, txtColor, 14, { lh:22, a:txtOpacity });
    var tabW = 16 + t.width + 4 + 12 + 16;
    var tab = bepFrame(tabW, TAB_H, { name:'Tab/' + label, r:4, clip:true });
    tab.fills = bepSolid(BEP_C.white);
    tab.x = cx;
    tab.y = TAB_Y;
    t.x = 16;
    t.y = 5;
    tab.appendChild(t);

    var closeIco = bepIcon('Line/Close', 12, closeColor);
    if (closeIco) {
      closeIco.opacity = closeOpacity;
      closeIco.x = 16 + t.width + 4;
      closeIco.y = 10;
      tab.appendChild(closeIco);
    }

    bar.appendChild(tab);
    cx += tabW + TAB_GAP;
  });

  var leftBtn = navBtn('left');
  leftBtn.x = 16;
  leftBtn.y = 8;
  bar.appendChild(leftBtn);

  var rightBtn = navBtn('right');
  rightBtn.x = totalWidth - 16 - 32;
  rightBtn.y = 8;
  bar.appendChild(rightBtn);

  return bar;
}

// ── § 7d 卡片内页签（置于内容卡片内部，不替代 TitleBar）────────────────────

/**
 * 卡片内页签（用于详情卡片、图表卡片等内容区内部切换）
 * tabs: 标签文字数组；activeIdx: 当前选中索引；totalWidth: 卡片外宽，通常为 CARD_W
 * opts.inset: 左右内缩，默认 24（与 Card 内边距一致）
 *
 * Figma 真源：
 *   BeP Admin Kit Sketch V1.1.0 / node 87:62879
 *   官方组件：4.Navigation/5.Tabs标签/基础标签/基础标签
 *
 * 结构：
 *   容器高 54px，透明占位背景
 *   内容左右内缩 24px，底边 1px rgba(0,0,0,0.10)
 *   标签从 x=24 开始横排，gap=16px
 *   标签高 54px，文字 14/22 Regular，y=16
 *   选中态文字主色，底部 2px 主色下划线
 *   默认态文字 rgba(0,0,0,0.65)，左右 padding=1px
 */
function bepCardTabs(tabs, activeIdx, totalWidth, opts) {
  tabs = tabs || [];
  activeIdx = (activeIdx !== undefined) ? activeIdx : 0;
  totalWidth = totalWidth || 1200;
  opts = opts || {};
  var inset = (opts.inset !== undefined) ? opts.inset : 24;
  var lineW = Math.max(0, totalWidth - inset * 2);

  var bar = bepFrame(totalWidth, 54, { name:'CardTabs', clip:true });
  bar.fills = [];
  bar.appendChild(bepRect(lineW, 1, B, { a:0.10, x:inset, y:53 }));

  var x = inset;
  var GAP = 16;
  for (var i = 0; i < tabs.length; i++) {
    var active = i == activeIdx;
    var color = active ? BEP_C.primary : B;
    var op = active ? 1 : 0.65;
    var t = bepText(tabs[i], color, 14, { lh:22, a:op });
    var itemPad = active ? 0 : 1;
    t.x = x + itemPad;
    t.y = 16;
    bar.appendChild(t);
    if (active) {
      bar.appendChild(bepRect(t.width, 2, BEP_C.primary, { x:x, y:52 }));
    }
    x = x + t.width + itemPad * 2 + GAP;
  }
  return bar;
}

// ── § 7d 已选操作栏（表格多选后的批量操作栏）────────────────────────────────

/**
 * 已选操作栏（Figma实测：表格-已选操作栏）
 * count  : 已选数量（数字）
 * actions: 批量操作按钮标签数组，如 ['删除','导出']（Secondary Small 28px）
 * tableW : 宽度（默认 TABLE_W=1152）
 *
 * 结构：
 *   h=48，背景 rgba(0,0,0,0.04)，底边 rgba(0,0,0,0.10)
 *   padding 左右24，内部 gap=16
 *   "已选择N项" 12px rgba(0,0,0,0.65)
 *   "取消选择" 12px primary，gap=16
 *   操作按钮：h=28，padding=8 LR，gap=8，Secondary样式
 */
function bepSelectionBar(count, actions, tableW) {
  tableW  = tableW  || 1152;
  actions = actions || [];
  count   = count   || 0;

  var bar = bepFrame(tableW, 48, { name:'SelectionBar', clip:false });
  bar.fills = bepSolid(B, 0.04);
  bar.appendChild(bepRect(tableW, 1, B, { a:0.10, x:0, y:47 }));

  var cx = 24;

  // "已选择N项"
  var countTxt = bepText('已选择 ' + count + ' 项', B, 12, { lh:20, a:0.65 });
  countTxt.x = cx; countTxt.y = 14;
  bar.appendChild(countTxt);
  cx += countTxt.width + 16;

  // "取消选择"
  var cancelTxt = bepText('取消选择', BEP_C.primary, 12, { lh:22 });
  cancelTxt.x = cx; cancelTxt.y = 13;
  bar.appendChild(cancelTxt);
  cx += cancelTxt.width + 16;

  // 操作按钮（Secondary Small，h=28，padding=8 LR）
  actions.forEach(function(label, i) {
    var tmpT = bepText(label, B, 14, { lh:22 });
    var btnW = tmpT.width + 16;  // padding 8+8
    tmpT.remove();

    var btn = bepFrame(btnW, 28, { name:'BatchBtn/' + label, clip:true });
    btn.fills       = bepSolid(BEP_C.white);
    btn.cornerRadius = 4;
    btn.strokes     = bepSolid(B, 0.15);
    btn.strokeWeight = 1;
    btn.strokeAlign  = 'INSIDE';

    var t = bepText(label, B, 14, { lh:22, a:0.65 });
    t.x = 8; t.y = 3;
    btn.appendChild(t);

    btn.x = cx; btn.y = 10;
    bar.appendChild(btn);
    cx += btnW + (i < actions.length - 1 ? 8 : 0);
  });

  return bar;
}

/**
 * 完整页头（TopBar + TitleBar，总高96px）
 */
function bepHeader(title, breadcrumbs, totalWidth) {
  totalWidth = totalWidth || 1440;
  var wrap = bepFrame(totalWidth, 96, { name:'Header', clip:false });
  wrap.fills = bepSolid(BEP_C.white);
  var top   = bepTopBar(totalWidth);
  var title_ = bepTitleBar(title, breadcrumbs, totalWidth);
  title_.y = 48;
  wrap.appendChild(top);
  wrap.appendChild(title_);
  return wrap;
}

// ── § 7e 对象标题摘要 / 页头标题型 ───────────────────────────────────────────

/**
 * 对象标题摘要（复合组件）
 *
 * opts: {
 *   width       : 宽度（默认 760）
 *   title       : 主标题
 *   subtitle    : 辅助说明
 *   imageNode   : 可选，56×56 图片节点
 *   status      : 可选，{ label:'已上架', type:'success' }，点状态
 *   tags        : 可选，[{ label:'实物商品', type:'warning', style:'solid' }]
 * }
 */
function bepObjectTitle(opts) {
  opts = opts || {};
  var width = opts.width || 760;
  var title = opts.title || '页面标题';
  var subtitle = opts.subtitle || '';
  var TITLE_ROW_H = opts.height || 56;
  var IMAGE_W = 56;
  var IMAGE_GAP = 16;
  var wrap = bepFrame(width, TITLE_ROW_H, { name:'ObjectTitle/对象标题摘要', clip:false });
  wrap.fills = [];

  var leftX = 0;
  if (opts.imageNode) {
    var imgNode = opts.imageNode;
    imgNode.x = 0;
    imgNode.y = 0;
    wrap.appendChild(imgNode);
    leftX = IMAGE_W + IMAGE_GAP;
  }

  var textW = Math.max(240, width - leftX);
  var textCol = bepFrame(textW, TITLE_ROW_H, { name:'ObjectTitle/Text', clip:false });
  textCol.fills = [];
  textCol.x = leftX;
  textCol.y = 0;
  wrap.appendChild(textCol);

  var titleLine = bepFrame(textW, 28, { name:'ObjectTitle/TitleLine', clip:false });
  titleLine.fills = [];
  textCol.appendChild(titleLine);

  var titleText = bepText(title, B, 20, { style:'Medium', lh:28, a:0.85 });
  titleText.x = 0;
  titleText.y = 0;
  titleLine.appendChild(titleText);
  var tx = titleText.width + 12;

  if (opts.status && opts.status.label) {
    var dotColor = opts.status.color || (opts.status.type === 'success' ? BEP_C.success : BEP_C.primary);
    var dotWrap = bepFrame(6, 6, { name:'StatusDot', r:3, clip:true });
    dotWrap.fills = bepSolid(dotColor);
    dotWrap.x = tx;
    dotWrap.y = 11;
    titleLine.appendChild(dotWrap);
    tx += 6 + 10;
    var st = bepText(opts.status.label, B, 14, { lh:22, a:0.65 });
    st.x = tx;
    st.y = 3;
    titleLine.appendChild(st);
    tx += st.width + 12;
  }

  (opts.tags || []).forEach(function(tagDef) {
    var tag = bepTag(tagDef.label || '', tagDef.type || 'info', tagDef.style || 'outline');
    tag.x = tx;
    tag.y = 3;
    titleLine.appendChild(tag);
    tx += tag.width + 8;
  });

  if (subtitle) {
    var sub = bepText(subtitle, B, 14, { lh:22, a:0.45 });
    sub.name = 'Subtitle';
    sub.x = 0;
    sub.y = 34;
    textCol.appendChild(sub);
  }

  return wrap;
}

/**
 * 页头标题型（Figma 真源：凤凰会后台 node 1044:10445）
 *
 * opts: {
 *   width       : 宽度（默认 1232 = CANVAS_W - SIDE_W）
 *   title       : 主标题
 *   subtitle    : 辅助说明
 *   imageNode   : 可选，56×56 图片节点
 *   status      : 可选，{ label:'已上架', type:'success' }，点状态
 *   tags        : 可选，[{ label:'实物商品', type:'warning', style:'solid' }]
 *   actions     : 可选，[{ label:'下架', type:'secondary' }, { label:'编辑', type:'primary-outline' }, { label:'下发门店', type:'primary' }]
 *   tabs        : 可选，['商品信息','操作记录']
 *   activeTab   : tabs 当前选中索引
 * }
 *
 * 组合形态：
 *   标题 / 标题+操作按钮 / 标题+Tabs / 标题+操作按钮+Tabs
 */
function bepHeaderTitle(opts) {
  opts = opts || {};
  var width = opts.width || 1232;
  var title = opts.title || '页面标题';
  var subtitle = opts.subtitle || '';
  var actions = opts.actions || [];
  var tabs = opts.tabs || [];
  var activeTab = opts.activeTab || 0;
  var PAD_X = 24;
  var TOP_PAD = 24;
  var GAP = 16;
  var TITLE_ROW_H = 56;
  var TAB_H = 32;
  var BOTTOM_PAD_NO_TABS = 24;
  var contentW = width - PAD_X * 2;
  var hasTabs = tabs.length > 0;
  var totalH = TOP_PAD + TITLE_ROW_H + (hasTabs ? GAP + TAB_H : BOTTOM_PAD_NO_TABS);
  var wrap = bepFrame(width, totalH, { name:'HeaderTitle/页头标题型', clip:false });
  wrap.fills = bepSolid(BEP_C.white);

  var row = bepFrame(contentW, TITLE_ROW_H, { name:'HeaderTitle/Main', clip:false });
  row.fills = [];
  row.x = PAD_X;
  row.y = TOP_PAD;
  wrap.appendChild(row);

  var titleW = contentW - (actions.length ? 320 : 0);
  if (titleW < 240) titleW = 240;
  var objectTitle = bepObjectTitle({
    width: titleW,
    title: title,
    subtitle: subtitle,
    imageNode: opts.imageNode,
    status: opts.status,
    tags: opts.tags
  });
  objectTitle.x = 0;
  objectTitle.y = 0;
  row.appendChild(objectTitle);

  if (actions.length) {
    var actionNodes = actions.map(function(a) {
      var btn = bepButton(a.label, a.type || 'secondary', 32);
      if (btn.width < 88) {
        btn.resize(88, 32);
        var btnText = btn.findOne(function(n) { return n.type === 'TEXT'; });
        if (btnText) btnText.x = Math.round((88 - btnText.width) / 2);
      }
      return btn;
    });
    var totalActionsW = actionNodes.reduce(function(sum, btn, i) {
      return sum + btn.width + (i < actionNodes.length - 1 ? 8 : 0);
    }, 0);
    var ax = contentW - totalActionsW;
    actionNodes.forEach(function(btn, i) {
      btn.x = ax;
      btn.y = 12;
      row.appendChild(btn);
      ax += btn.width + (i < actionNodes.length - 1 ? 8 : 0);
    });
  }

  if (hasTabs) {
    var tabBar = bepHeaderTitleTabs(tabs, activeTab, contentW);
    tabBar.x = PAD_X;
    tabBar.y = TOP_PAD + TITLE_ROW_H + GAP;
    wrap.appendChild(tabBar);
  }

  return wrap;
}

function bepHeaderTitleTabs(tabs, activeIdx, width) {
  tabs = tabs || [];
  activeIdx = activeIdx || 0;
  width = width || 1200;
  var wrap = bepFrame(width, 32, { name:'HeaderTitleTabs', clip:true });
  wrap.fills = [];
  wrap.appendChild(bepRect(Math.max(0, width - 48), 1, B, { a:0.10, x:24, y:31 }));
  var x = 0;
  var GAP = 20;
  for (var i = 0; i < tabs.length; i++) {
    var active = i === activeIdx;
    var color = active ? BEP_C.primary : B;
    var op = active ? 1 : 0.65;
    var t = bepText(tabs[i], color, 14, { lh:22, a:op });
    t.x = x;
    t.y = 5;
    wrap.appendChild(t);
    if (active) wrap.appendChild(bepRect(t.width, 2, BEP_C.primary, { x:x, y:30 }));
    x += t.width + GAP;
  }
  return wrap;
}

// ── § 7b 面包屑（独立组件）────────────────────────────────────────────────────

/**
 * BeP 标准面包屑导航
 *
 * items : 字符串数组，如 ['系统管理', '菜单权限管理']
 *   · 最后一项 = 当前页，颜色 rgba(0,0,0,0.85)
 *   · 其余项   = 父级页，颜色 rgba(0,0,0,0.45)
 *   · 分隔符   = Line/Right-Arrow 12×12，rgba(0,0,0,0.25)
 *   · 文字与箭头两侧各 8px 间距
 *   · 高度 22px（与正文行高一致）
 *
 * 注：bepTitleBar 内部已内置面包屑渲染；
 *     此函数用于需要单独在页面其他位置显示面包屑的场景。
 */
function bepBreadcrumb(items) {
  if (!items || items.length === 0) {
    return bepFrame(0, 22, { name:'Breadcrumb' });
  }

  var GAP     = 8;   // 文字/图标两侧间距
  var ICO_SZ  = 12;
  var H       = 22;

  // 构建节点序列：text / arrow / text / arrow / …/ text(last)
  var seq = [];
  items.forEach(function(item, idx) {
    var isLast = (idx === items.length - 1);
    var t = bepText(item, B, 14, { lh:22, a: isLast ? 0.85 : 0.45 });
    seq.push({ node: t, w: t.width, isIcon: false });

    if (!isLast) {
      var ico = bepIcon('Line/Right-Arrow', ICO_SZ, B);
      if (ico) ico.opacity = 0.25;
      seq.push({ node: ico, w: ICO_SZ, isIcon: true });
    }
  });

  // 计算总宽（节点间均用 GAP 分隔）
  var totalW = seq.reduce(function(sum, n, i) {
    return sum + n.w + (i < seq.length - 1 ? GAP : 0);
  }, 0);

  var wrap = bepFrame(totalW, H, { name:'Breadcrumb' });
  var cx = 0;
  seq.forEach(function(n, i) {
    if (n.node) {
      n.node.x = cx;
      n.node.y = n.isIcon ? Math.round((H - ICO_SZ) / 2) : 0;
      wrap.appendChild(n.node);
    }
    cx += n.w + (i < seq.length - 1 ? GAP : 0);
  });

  return wrap;
}

// ── § 8  侧边栏辅助 ───────────────────────────────────────────────────────────

/** 侧边栏 Logo 区（高64px，深色背景）*/
function bepSidebarLogo(appName, appEnName, sideW) {
  sideW = sideW || 208;
  var area = bepFrame(sideW, 64, { name:'SidebarLogo', clip:false });
  area.fills = bepSolid(bepHex('002138'));
  // 图标方块
  var ico = bepRect(32, 32, BEP_C.primary, { r:6, x:24, y:16 });
  area.appendChild(ico);
  var letter = bepText('M', BEP_C.white, 14, { style:'Medium', lh:20, x:33, y:22 });
  area.appendChild(letter);
  // 文字
  var nm = bepText(appName || 'Mall 管理后台', BEP_C.white, 16, { style:'Medium', lh:22, x:64, y:12 });
  area.appendChild(nm);
  var sub = bepText(appEnName || 'MALL MANAGEMENT', BEP_C.white, 7, { lh:10, a:0.6, x:64, y:38 });
  area.appendChild(sub);
  return area;
}

/**
 * 侧边栏菜单项
 * level: 1（一级）/ 2（二级）/ 3（三级）
 * state: 'active'|'expanded'|'default'
 * iconKey: 可选 BeP 图标 key（只支持 BEP_ICONS 内图标）
 */
function bepSidebarItem(label, level, state, iconKey, sideW) {
  sideW = sideW || 208;
  level = level || 1;
  var isActive   = state === 'active';
  var isExpanded = state === 'expanded';
  var childOp    = (isActive || isExpanded) ? 1 : 0.5;
  var row = bepFrame(sideW, 48, { name:'L' + level + '·' + label, clip:false });

  // active 态只改变文字 opacity，背景与普通项相同，无竖线无高亮底色
  row.fills = bepSolid(level >= 2 ? bepHex('00182A') : bepHex('002138'));

  // 图标
  var hasIcon = iconKey && BEP_ICONS[iconKey];
  if (hasIcon) {
    var si = bepIcon(iconKey, 16, BEP_C.white);
    si.x = 24; si.y = 16; si.opacity = childOp;
    row.appendChild(si);
  }
  var textX = hasIcon ? 48 : 24;
  if (level === 2) textX = hasIcon ? 56 : 40;
  if (level === 3) textX = hasIcon ? 72 : 56;
  var lt = bepText(label, BEP_C.white, 14, { lh:22, x:textX, y:13 });
  lt.opacity = childOp;
  row.appendChild(lt);

  // 展开箭头（一级展开时）：展开态→∧ PutAway，收起态→∨ DropDown
  if (level === 1 && isExpanded) {
    var expIco = bepIcon('Line/PutAway-Arrow', 12, BEP_C.white);
    if (expIco) { expIco.x = 186; expIco.y = 18; expIco.opacity = childOp; row.appendChild(expIco); }
  }
  return row;
}
// ── § 9a 单行筛选（特殊情况：条件少 + 右侧操作按钮）────────────────────────

/**
 * 单行筛选区（≤2个筛选条件，宽 tableW，高 32px，无上下padding）
 * filters: [{label, placeholder, width}]  e.g. [{label:'菜单名称', placeholder:'请输入', width:200}]
 * addLabel: 右侧操作按钮文案（默认 '+ 新增'）
 * tableW: 表格宽度（默认 1152）
 */
function bepFilterRow(filters, addLabel, tableW) {
  tableW  = tableW  || 1152;
  addLabel = addLabel || '+ 新增';
  var wrap = bepFrame(tableW, 32, { name:'FilterRow' });
  // 左侧筛选字段
  var lx = 0;
  filters.forEach(function(f, idx) {
    var lbl = bepText(f.label + ':', B, 14, { lh:22, a:0.85, x:lx, y:5 });
    wrap.appendChild(lbl);
    lx += lbl.width + 8;
    var inp = bepInput(f.placeholder || '请输入', f.width || 200, 32);
    inp.x = lx; inp.y = 0;
    wrap.appendChild(inp);
    lx += (f.width || 200) + 8;
  });
  // 查询按钮
  var qBtn = bepButton('查询', 'secondary', 32);
  qBtn.x = lx; qBtn.y = 0;
  wrap.appendChild(qBtn);
  // 右侧新增等操作按钮
  var addBtn = bepButton(addLabel, 'primary', 32);
  addBtn.x = tableW - addBtn.width;
  addBtn.y = 0;
  wrap.appendChild(addBtn);
  return wrap;
}


// ── § 10  筛选区·网格版（3列，查询/重置右对齐，超6条件自动折叠）────────────

/**
 * bepFilterGrid — 通用多条件筛选区
 *
 * filters : [{label, placeholder, type, width}]
 *   type: 'input'（默认）| 'select' | 'date' | 'daterange' | 'time' | 'timerange' | 'datetime' | 'datetimerange'
 *
 * tableW  : 容器总宽（默认 1152）
 * collapsed: true=折叠态；false=展开态（默认）
 *
 * 布局规则：
 *   · 三列等宽（colW = floor((tableW-8*2)/3)）
 *   · 标题区固定 112px、右对齐、含冒号；标题与控件间距 12px
 *   · 查询/重置（+展开/收起）按钮组右对齐
 *   · 按钮组落在第3行 → 触发折叠显示
 *   · 折叠态（方案乙）：只显示前5个条件，按钮组放第2行末右侧
 *   · 每行高度 = 32px（控件高，无上下padding）；行间距 = 16px
 */
function bepFilterGrid(filters, tableW, collapsed) {
  tableW   = tableW   || 1152;
  collapsed = (collapsed === true);

  var COL     = 3;
  var COL_GAP = 8;    // 列间距
  var LABEL_W = 112;  // 标题固定宽度
  var CTR_GAP = 12;   // 标题与控件间距
  var CTRL_H  = 32;   // 控件高度（行高，无上下 padding）
  var ROW_GAP = 16;   // 行间距
  var BTN_GAP = 8;    // 按钮间距

  var colW  = Math.floor((tableW - COL_GAP * (COL - 1)) / COL);
  var ctrlW = colW - LABEL_W - CTR_GAP;

  // 折叠判断：未折叠时按钮落在第3行（rowIdx 2）则需要折叠
  var needCollapse = Math.floor(filters.length / COL) >= 2;

  // 实际渲染条件（方案乙：折叠态最多5条）
  var renderFs = (!needCollapse || !collapsed) ? filters : filters.slice(0, 5);

  var rBtnRow = Math.floor(renderFs.length / COL);  // 按钮所在行（0-based）

  var totalRows = rBtnRow + 1;
  var totalH    = totalRows * CTRL_H + (totalRows - 1) * ROW_GAP;

  // 主容器（自动布局：垂直，行间距16，无上下padding）
  var wrap = bepFrame(tableW, totalH, { name:'FilterGrid', clip:false });
  wrap.layoutMode = 'VERTICAL';
  wrap.primaryAxisAlignItems = 'MIN';
  wrap.counterAxisAlignItems = 'MIN';
  wrap.primaryAxisSizingMode = 'AUTO';
  wrap.counterAxisSizingMode = 'FIXED';
  wrap.itemSpacing = ROW_GAP;
  wrap.paddingTop = 0; wrap.paddingBottom = 0;
  wrap.paddingLeft = 0; wrap.paddingRight = 0;

  // ── 单个筛选字段（标题 + 控件）──
  function makeField(f) {
    // 字段容器（水平自动布局，垂直居中）
    var field = bepFrame(colW, CTRL_H, { name:'Field/' + (f.label || ''), clip:false });
    field.layoutMode = 'HORIZONTAL';
    field.counterAxisAlignItems = 'CENTER';
    field.itemSpacing = CTR_GAP;

    // 标题区（固定 112px，手动右对齐文字，不使用自动布局避免 HUG 缩宽）
    var lblArea = bepFrame(LABEL_W, CTRL_H, { name:'Label', clip:false });

    var lbl = bepText(f.label || '', B, 14, { lh:22, a:0.85 });
    // 右对齐：令文字右边缘贴齐 112px
    lbl.x = LABEL_W - lbl.width;
    lbl.y = Math.round((CTRL_H - 22) / 2);
    lblArea.appendChild(lbl);

    field.appendChild(lblArea);
    // 在父级自动布局中保持固定宽 112px
    lblArea.layoutSizingHorizontal = 'FIXED';
    lblArea.layoutSizingVertical   = 'FIXED';

    // 控件
    var ctrl;
    if      (f.type === 'select')    ctrl = bepSelect(f.placeholder || '请选择', ctrlW, CTRL_H);
    else if (f.type === 'cascader')  ctrl = bepCascader(f.placeholder || '请选择', ctrlW, CTRL_H, { value:f.value, multiple:f.multiple });
    else if (f.type === 'date')      ctrl = bepDate(f.placeholder || '请选择日期', ctrlW, CTRL_H);
    else if (f.type === 'daterange') ctrl = bepDateRange(ctrlW, CTRL_H);
    else if (f.type === 'time')      ctrl = bepTime(f.placeholder || '请选择时间', ctrlW, CTRL_H);
    else if (f.type === 'timerange') ctrl = bepTimeRange(ctrlW, CTRL_H);
    else if (f.type === 'datetime')  ctrl = bepDateTime(f.placeholder || '请选择日期', ctrlW, CTRL_H);
    else if (f.type === 'datetimerange') ctrl = bepDateTimeRange(ctrlW, CTRL_H);
    else                             ctrl = bepInput(f.placeholder || '请输入',   ctrlW, CTRL_H);
    field.appendChild(ctrl);
    ctrl.layoutSizingHorizontal = 'FIXED';
    ctrl.layoutSizingVertical   = 'FIXED';

    return field;
  }

  // ── 展开/收起：筛选区固定使用文字按钮 + 图标 ──
  function makeToggleBtn() {
    var label  = collapsed ? '展开' : '收起';
    var icoKey = collapsed ? 'Line/DropDown-Arrow' : 'Line/PutAway-Arrow';
    var btn = bepButton(label, 'text', CTRL_H, { iconKey:icoKey, iconPosition:'right' });
    btn.name = collapsed ? 'BtnExpand' : 'BtnCollapse';
    return btn;
  }

  // ── 按钮组（查询 / 重置 / [展开|收起]）──
  function makeBtnGroup() {
    var qBtn = bepButton('查询', 'primary',   CTRL_H);
    var rBtn = bepButton('重置', 'secondary', CTRL_H);
    var tBtn = needCollapse ? makeToggleBtn() : null;

    var TOGGLE_GAP = 16;  // 展开/收起与前面按钮的间距（Figma实测16px）
    var totalW = qBtn.width + BTN_GAP + rBtn.width;
    if (tBtn) totalW += TOGGLE_GAP + tBtn.width;

    var grp = bepFrame(totalW, CTRL_H, { name:'BtnGroup' });
    var bx  = 0;
    qBtn.x = bx; qBtn.y = 0; grp.appendChild(qBtn); bx += qBtn.width + BTN_GAP;
    rBtn.x = bx; rBtn.y = 0; grp.appendChild(rBtn);
    if (tBtn) { bx += rBtn.width + TOGGLE_GAP; tBtn.x = bx; tBtn.y = 0; grp.appendChild(tBtn); }
    return grp;
  }

  // ── 按行渲染 ──
  for (var rowIdx = 0; rowIdx <= rBtnRow; rowIdx++) {
    var isLastRow = (rowIdx === rBtnRow);

    // 行容器（自动布局：水平，垂直居中）
    var row = bepFrame(tableW, CTRL_H, { name:'Row' + rowIdx, clip:false });
    row.layoutMode = 'HORIZONTAL';
    row.counterAxisAlignItems = 'CENTER';
    row.itemSpacing = COL_GAP;
    row.paddingTop = 0; row.paddingBottom = 0;
    row.paddingLeft = 0; row.paddingRight = 0;

    // 本行的条件
    var rowStart = rowIdx * COL;
    var rowEnd   = Math.min(rowStart + COL, renderFs.length);
    for (var fi = rowStart; fi < rowEnd; fi++) {
      var fld = makeField(renderFs[fi]);
      row.appendChild(fld);
      fld.layoutSizingHorizontal = 'FIXED';
      fld.layoutSizingVertical   = 'FIXED';
    }

    if (isLastRow) {
      // 弹性间隔（把按钮组推到最右）
      var spacer = bepFrame(1, CTRL_H, { name:'Spacer' });
      row.appendChild(spacer);
      spacer.layoutGrow = 1;

      // 按钮组
      var btnGrp = makeBtnGroup();
      row.appendChild(btnGrp);
      btnGrp.layoutSizingHorizontal = 'FIXED';
      btnGrp.layoutSizingVertical   = 'FIXED';
    }

    wrap.appendChild(row);
    row.layoutSizingHorizontal = 'FIXED';
    row.layoutSizingVertical   = 'HUG';
  }

  return wrap;
}

// ── § 10b 单选按钮组 RadioGroup ───────────────────────────────────────────────

/**
 * bepRadioGroup — 水平单选组（Figma实测：2.DataEntry/5.Radio单选框）
 * options  : 字符串数组或 [{label, value, state, disabled}] 数组
 * activeVal: 当前选中项的 label 或 value
 * opts/gap : 数字时兼容旧 gap；对象支持 {gap, variant:'default'|'button', disabled}
 */
function bepRadioGroup(options, activeVal, opts) {
  options = options || [];
  if (typeof opts === 'number') opts = { gap: opts };
  opts = opts || {};

  if (opts.variant === 'button') return bepRadioButtonGroup(options, activeVal, opts);

  var gap = (opts.gap === 0 || opts.gap) ? opts.gap : 16;

  var wrap = bepFrame(1, 22, { name:'RadioGroup', clip:false });
  wrap.fills = [];

  var cx = 0;
  options.forEach(function(opt, i) {
    var label    = (typeof opt === 'string') ? opt : (opt.label || '');
    var value    = (typeof opt === 'string') ? opt : (opt.value || opt.label || '');
    var state    = (typeof opt === 'string') ? (opts.state || 'default') : (opt.state || opts.state || 'default');
    var disabled = !!(opts.disabled || (typeof opt !== 'string' && opt.disabled));
    var isActive = (activeVal === label || activeVal === value);

    var item = bepFrame(1, 22, { name:'RadioItem/' + label, clip:false });
    item.fills = [];
    if (disabled) item.opacity = 0.5;

    var circle = bepFrame(16, 16, { name:'Radio', clip:true });
    circle.cornerRadius = 8;
    circle.x = 0; circle.y = 3;
    circle.fills       = bepSolid(BEP_C.white);
    circle.strokeWeight = 1; circle.strokeAlign = 'INSIDE';

    if (isActive) {
      circle.strokes     = bepSolid(BEP_C.primary);
      var dot = bepRect(8, 8, BEP_C.primary, { r:4, x:4, y:4 });
      circle.appendChild(dot);
    } else if (state === 'hover') {
      circle.strokes     = bepSolid(BEP_C.primaryH);
    } else {
      circle.strokes     = bepSolid(B, 0.15);
    }
    item.appendChild(circle);

    var t = bepText(label, B, 14, { lh:22, a:0.65, x:24, y:0 });
    item.appendChild(t);
    item.resize(24 + t.width, 22);
    item.x = cx; item.y = 0;
    wrap.appendChild(item);

    cx += item.width + (i < options.length - 1 ? gap : 0);
  });

  wrap.resize(cx, 22);
  return wrap;
}

function bepRadioButtonGroup(options, activeVal, opts) {
  options = options || [];
  opts = opts || {};

  var wrap = bepFrame(1, 32, { name:'RadioButtonGroup', clip:false });
  wrap.fills = [];

  var cx = 0;
  options.forEach(function(opt) {
    var label    = (typeof opt === 'string') ? opt : (opt.label || '');
    var value    = (typeof opt === 'string') ? opt : (opt.value || opt.label || '');
    var state    = (typeof opt === 'string') ? (opts.state || 'default') : (opt.state || opts.state || 'default');
    var disabled = !!(opts.disabled || (typeof opt !== 'string' && opt.disabled));
    var isActive = (activeVal === label || activeVal === value);

    var measure = bepText(label, B, 14, { lh:22, a:0.65 });
    var segW = opts.itemWidth || (measure.width + 32);
    measure.remove();

    var seg = bepFrame(segW, 32, { name:'RadioButton/' + label, r:0, clip:true });
    seg.x = cx; seg.y = 0;
    seg.fills = bepSolid(BEP_C.white);
    seg.strokeWeight = 1; seg.strokeAlign = 'INSIDE';

    var textColor = '#666666';
    if (isActive) {
      seg.strokes = bepSolid(BEP_C.primary);
      textColor = BEP_C.primary;
    } else if (state === 'hover') {
      seg.strokes = bepSolid(BEP_C.primaryH);
      textColor = BEP_C.primaryH;
    } else {
      seg.strokes = bepSolid('#D9D9D9');
    }
    if (disabled) seg.opacity = 0.5;

    var t = bepText(label, textColor, 14, { lh:22, x:0, y:5 });
    t.x = (segW - t.width) / 2;
    seg.appendChild(t);
    wrap.appendChild(seg);
    cx += segW;
  });

  wrap.resize(cx, 32);
  return wrap;
}

// ── § 10c 多选按钮组 CheckboxGroup ───────────────────────────────────────────

/**
 * bepCheckboxGroup — 水平多选组（Figma实测：2.DataEntry/4.Checkbox多选框）
 * options : 字符串数组或 [{label, value, state, disabled}]
 * selected: 已选值数组（label 或 value）
 * opts/gap: 数字时兼容旧 gap；对象支持 {gap, disabled}
 */
function bepCheckboxGroup(options, selected, opts) {
  options  = options  || [];
  selected = selected || [];
  if (typeof opts === 'number') opts = { gap: opts };
  opts = opts || {};
  var gap = (opts.gap === 0 || opts.gap) ? opts.gap : 16;

  var wrap = bepFrame(1, 22, { name:'CheckboxGroup', clip:false });
  wrap.fills = [];

  var cx = 0;
  options.forEach(function(opt, i) {
    var label     = (typeof opt === 'string') ? opt : (opt.label || '');
    var value     = (typeof opt === 'string') ? opt : (opt.value || opt.label || '');
    var state     = (typeof opt === 'string') ? (opts.state || 'default') : (opt.state || opts.state || 'default');
    var disabled  = !!(opts.disabled || (typeof opt !== 'string' && opt.disabled));
    var isChecked = (selected.indexOf(label) !== -1 || selected.indexOf(value) !== -1);

    var item = bepFrame(1, 22, { name:'CheckboxItem/' + label, clip:false });
    item.fills = [];
    if (disabled) item.opacity = 0.5;

    var cb = bepFrame(16, 16, { name:'Checkbox', clip:true });
    cb.cornerRadius = 2;
    cb.x = 0; cb.y = 3;
    cb.strokeWeight = 1; cb.strokeAlign = 'INSIDE';

    if (isChecked) {
      cb.fills       = bepSolid(BEP_C.primary);
      cb.strokes     = bepSolid(BEP_C.primary);
      var ck = bepIcon('Line/check', 10, BEP_C.white);  // BeP 标准 ✓ 图标
      if (ck) { ck.x = 3; ck.y = 3; cb.appendChild(ck); }
    } else if (state === 'hover') {
      cb.fills       = bepSolid(BEP_C.white);
      cb.strokes     = bepSolid(BEP_C.primaryH);
    } else {
      cb.fills       = bepSolid(BEP_C.white);
      cb.strokes     = bepSolid(B, 0.15);
    }
    item.appendChild(cb);

    var t = bepText(label, B, 14, { lh:22, a:0.65, x:24, y:0 });
    item.appendChild(t);
    item.resize(24 + t.width, 22);
    item.x = cx; item.y = 0;
    wrap.appendChild(item);

    cx += item.width + (i < options.length - 1 ? gap : 0);
  });

  wrap.resize(cx, 22);
  return wrap;
}

// ── § 10d 上传 Upload ───────────────────────────────────────────────────────

/**
 * bepUploadBtn — 上传按钮（Figma实测：2.DataEntry/12.Upload上传/点击上传）
 * label : 按钮文字（默认 '点击上传'）
 * height: 高度（默认 32）
 * opts  : { state:'default'|'hover', disabled }
 */
function bepUploadBtn(label, height, opts) {
  if (typeof height === 'object') { opts = height; height = 32; }
  label  = label  || '点击上传';
  height = height || 32;
  opts   = opts   || {};

  var H_PAD = 16, GAP = 8, ICO_SZ = 16;
  var tmpT = bepText(label, B, 14, { lh:22, a:0.65 });
  var textW = tmpT.width; tmpT.remove();
  var btnW = H_PAD + ICO_SZ + GAP + textW + H_PAD;

  var btn = bepFrame(btnW, height, { name:'UploadBtn', clip:true });
  btn.fills = bepSolid(BEP_C.white);
  btn.strokes = bepSolid(opts.state === 'hover' ? BEP_C.primaryH : B, opts.state === 'hover' ? 1 : 0.15);
  btn.strokeWeight = 1; btn.strokeAlign = 'INSIDE';
  btn.cornerRadius = 4;
  if (opts.disabled) btn.opacity = 0.5;

  var color = opts.state === 'hover' ? BEP_C.primaryH : B;
  var ico = bepIcon('Line/upload', ICO_SZ, color);
  if (ico) { ico.x = H_PAD; ico.y = Math.round((height - ICO_SZ) / 2); btn.appendChild(ico); }

  var t = bepText(label, color, 14, { lh:22, a:opts.state === 'hover' ? 1 : 0.65 });
  t.x = H_PAD + ICO_SZ + GAP; t.y = Math.round((height - 22) / 2);
  btn.appendChild(t);

  return btn;
}

function bepUploadClick(label, tip, opts) {
  opts = opts || {};
  label = label || '点击上传';
  tip = tip || '仅支持xls、txt、png、jpg格式，大小在500KB以内';

  var btn = bepUploadBtn(label, 32, opts);
  var tipT = bepText(tip, B, 12, { lh:20, a:0.45 });
  var w = Math.max(opts.width || 274, btn.width, tipT.width);
  var wrap = bepFrame(w, 60, { name:'UploadClick', clip:false });
  wrap.fills = [];

  btn.x = 0; btn.y = 0;
  wrap.appendChild(btn);
  tipT.x = 0; tipT.y = 40;
  wrap.appendChild(tipT);
  return wrap;
}

function bepUploadFileRow(file, opts) {
  opts = opts || {};
  if (typeof file === 'string') file = { name:file };
  file = file || {};
  var state = opts.state || file.state || 'default';
  var w = opts.width || 280;
  var row = bepFrame(w, 28, { name:'UploadFileRow/' + state, clip:true });
  row.fills = bepSolid(state === 'hover' ? BEP_C.secondary : B, state === 'hover' ? 1 : 0.04);

  var nameColor = state === 'error' ? BEP_C.danger : B;
  var paper = bepIcon('Line/Paperclip', 16, nameColor);
  paper.x = 8; paper.y = 6;
  row.appendChild(paper);

  var rightIcons = [];
  if (state === 'uploading') rightIcons = ['Line/Loading'];
  else if (state === 'hover') rightIcons = ['Line/Download', 'Line/Trash'];
  else if (state === 'error') rightIcons = ['Line/Trash'];

  var reserved = rightIcons.length ? 8 + rightIcons.length * 24 : 8;
  var txt = bepTableText(file.name || '文件名称.txt', nameColor, w - 32 - reserved, { x:32, y:3, a:state === 'error' ? 1 : 0.65 });
  row.appendChild(txt);

  rightIcons.forEach(function(iconKey, i) {
    var color = iconKey === 'Line/Loading' ? B : bepHex('666666');
    var icon = bepIcon(iconKey, 16, color);
    icon.x = w - 24 * (rightIcons.length - i);
    icon.y = 6;
    if (iconKey === 'Line/Loading') icon.name = 'LoadingRotating';
    row.appendChild(icon);
  });

  return row;
}

function bepUploadFileList(files, opts) {
  files = files || [];
  opts = opts || {};
  var w = opts.width || 280;
  var gap = opts.gap === 0 ? 0 : (opts.gap || 2);
  var h = files.length ? files.length * 28 + (files.length - 1) * gap : 28;
  var wrap = bepFrame(w, h, { name:'UploadFileList', clip:false });
  wrap.fills = [];
  var cy = 0;
  files.forEach(function(file) {
    var row = bepUploadFileRow(file, { width:w });
    row.x = 0; row.y = cy;
    wrap.appendChild(row);
    cy += 28 + gap;
  });
  return wrap;
}

function bepUploadDragger(opts) {
  opts = opts || {};
  var w = opts.width || 360;
  var boxH = opts.boxHeight || 160;
  var tip = opts.tip || '支持单个或批量上传';
  var state = opts.state || 'default';
  var borderColor = state === 'hover' ? BEP_C.primaryH : B;

  var wrap = bepFrame(w, boxH + 28, { name:'UploadDragger/' + state, clip:false });
  wrap.fills = [];

  var box = bepFrame(w, boxH, { name:'DragArea', r:2, clip:true });
  box.fills = [];
  box.strokes = bepSolid(borderColor, state === 'hover' ? 1 : 0.15);
  box.strokeWeight = 1; box.strokeAlign = 'INSIDE';
  box.dashPattern = [4, 2];
  wrap.appendChild(box);

  var cloud = bepIcon('Line/upload-cloud', 48, BEP_C.primary);
  cloud.x = Math.round((w - 48) / 2);
  cloud.y = 36;
  box.appendChild(cloud);

  var mainText = bepText(opts.title || '点击或将文件拖拽到这里上传', B, 14, { lh:22, a:0.65 });
  mainText.x = Math.round((w - mainText.width) / 2);
  mainText.y = 92;
  box.appendChild(mainText);

  var subText = bepText(opts.desc || '支持扩展名：xls、txt、png、jpg', B, 12, { lh:20, a:0.45 });
  subText.x = Math.round((w - subText.width) / 2);
  subText.y = 116;
  box.appendChild(subText);

  var tipText = bepText(tip, B, 12, { lh:20, a:0.45, x:0, y:boxH + 8 });
  wrap.appendChild(tipText);
  return wrap;
}

function bepImageUploadCell(item, opts) {
  opts = opts || {};
  if (typeof item === 'string') item = { state:item };
  item = item || {};
  var state = item.state || opts.state || 'default';
  var size = opts.size || 100;
  var cell = bepFrame(size, size, { name:'ImageUploadCell/' + state, r:2, clip:true });
  cell.fills = bepSolid(BEP_C.white);
  cell.strokeWeight = 1; cell.strokeAlign = 'INSIDE';
  cell.strokes = bepSolid(state === 'error' ? BEP_C.danger : (state === 'default' ? B : BEP_C.primaryH), state === 'default' ? 0.15 : 1);
  cell.dashPattern = (state === 'success' || state === 'success-hover' || state === 'error') ? [] : [4, 2];

  if (state === 'success' || state === 'success-hover') {
    var img = bepRect(size, size, item.color || bepHex('D8E8EF'), { r:2, x:0, y:0 });
    img.name = 'ImagePreview';
    cell.appendChild(img);
    var band = bepRect(size, size, B, { a: state === 'success-hover' ? 0.6 : 0, r:2, x:0, y:0 });
    if (state === 'success-hover') {
      cell.appendChild(band);
      var zoom = bepIcon('Line/zoom-in', 16, BEP_C.white);
      zoom.x = 26; zoom.y = 42; cell.appendChild(zoom);
      var trash = bepIcon('Line/Trash', 16, BEP_C.white);
      trash.x = 58; trash.y = 42; cell.appendChild(trash);
    }
    return cell;
  }

  var iconKey = state === 'uploading' ? 'Line/Loading' : 'Line/Add';
  var iconColor = state === 'error' ? BEP_C.danger : BEP_C.primary;
  var icon = bepIcon(iconKey, 24, iconColor);
  icon.x = 38; icon.y = 24;
  if (state === 'uploading') icon.name = 'LoadingRotating';
  cell.appendChild(icon);

  var label = state === 'error' ? '上传失败' : (state === 'uploading' ? '上传中' : (item.label || '点击上传'));
  var labelColor = state === 'error' ? BEP_C.danger : B;
  var lh = state === 'error' ? 16 : 20;
  var text = bepText(label, labelColor, 12, { lh:lh, a:state === 'error' ? 1 : 0.65 });
  text.x = Math.round((size - text.width) / 2);
  text.y = state === 'error' ? 58 : 56;
  cell.appendChild(text);

  if (state === 'error-hover') {
    var mask = bepRect(size, size, B, { a:0.6, r:2, x:0, y:0 });
    cell.appendChild(mask);
    var del = bepIcon('Line/Trash', 16, BEP_C.white);
    del.x = 42; del.y = 42; cell.appendChild(del);
  }

  return cell;
}

function bepImageUpload(items, opts) {
  items = items || [];
  opts = opts || {};
  var size = opts.size || 100;
  var gap = opts.gap || 8;
  var tip = opts.tip || '上传格式为jpg、png、jpeg图片格式，最多上传5张';
  var cells = items.length ? items.slice() : [{ state:'default' }];
  var cols = opts.cols || cells.length;
  var rows = Math.ceil(cells.length / cols);
  var w = cols * size + (cols - 1) * gap;
  var h = rows * size + (rows - 1) * gap + 28;
  var wrap = bepFrame(w, h, { name:'ImageUpload', clip:false });
  wrap.fills = [];

  cells.forEach(function(item, i) {
    var cell = bepImageUploadCell(item, { size:size });
    cell.x = (i % cols) * (size + gap);
    cell.y = Math.floor(i / cols) * (size + gap);
    wrap.appendChild(cell);
  });

  var tipText = bepText(tip, B, 12, { lh:20, a:0.45, x:0, y:rows * size + (rows - 1) * gap + 8 });
  wrap.appendChild(tipText);
  return wrap;
}

// ── § 10e 卡片 Card ──────────────────────────────────────────────────────────

/**
 * bepCard — 内容卡片（Figma实测：卡片页模板）
 *
 * opts : {
 *   width     : 卡片宽度（默认288）
 *   height    : 卡片高度（默认255）
 *   iconColor : 图标圆背景色（默认 BEP_C.primary）
 *   iconKey   : BEP_ICONS 图标名（可选）
 *   title     : 卡片标题
 *   descs     : [{label, value}] 描述行（最多3行，每行30px间距）
 *   actions   : 操作按钮标签数组，如 ['操作一','操作二','更多']
 *               最后一项若为'更多'，自动添加 ∨ 下拉箭头
 * }
 *
 * 规格（Figma实测）：
 *   卡片：288×255，r=4，白色底
 *   图标圆：44×44，x=24 y=24
 *   标题：16px Medium，x=80 y=34
 *   描述：x=24（label）/ x=96（value），y从80开始，行间距30px
 *   底部操作区：h=47，y=208，顶部1px分隔线，等分3列，文字居中，主色
 *   列间分隔：1px rgba(0,0,0,0.06)，高24px，居中
 */
function bepCard(opts) {
  opts = opts || {};
  var w          = opts.width     || 288;
  var h          = opts.height    || 255;
  var iconColor  = opts.iconColor || BEP_C.primary;
  var iconKey    = opts.iconKey;
  var title      = opts.title     || '卡片标题';
  var descs      = opts.descs     || [];
  var actions    = opts.actions   || [];

  var CARD_PAD = 24;
  var FOOTER_H = 47;
  var CIRC_SZ  = 44;

  var card = bepFrame(w, h, { name:'Card', r:4, clip:true });
  card.fills = bepSolid(BEP_C.white);

  // 图标圆
  card.appendChild(bepRect(CIRC_SZ, CIRC_SZ, iconColor, { r:CIRC_SZ/2, x:CARD_PAD, y:CARD_PAD }));
  if (iconKey) {
    var ico = bepIcon(iconKey, 24, BEP_C.white);
    if (ico) { ico.x = CARD_PAD + 10; ico.y = CARD_PAD + 10; card.appendChild(ico); }
  }

  // 标题
  var titleT = bepText(title, B, 16, { style:'Medium', lh:24, a:0.85 });
  titleT.x = CARD_PAD + CIRC_SZ + 12; titleT.y = CARD_PAD + 10;
  titleT.resize(Math.max(w - titleT.x - CARD_PAD, 24), 24);
  titleT.textAutoResize = 'NONE';
  titleT.textTruncation = 'ENDING';
  card.appendChild(titleT);

  // 描述行（label + value，间距30px）
  var descY = CARD_PAD + CIRC_SZ + 12;
  descs.forEach(function(d) {
    var lbl = bepText((d.label || '') + '：', B, 14, { lh:22, a:0.45, x:CARD_PAD, y:descY });
    lbl.resize(68, 22);
    lbl.textAutoResize = 'NONE';
    lbl.textTruncation = 'ENDING';
    card.appendChild(lbl);
    var val = bepText(d.value || '', B, 14, { lh:22, a:0.65, x:CARD_PAD + 72, y:descY });
    val.resize(Math.max(w - CARD_PAD * 2 - 72, 24), 22);
    val.textAutoResize = d.wrap === false ? 'NONE' : 'HEIGHT';
    val.textTruncation = d.wrap === false ? 'ENDING' : 'DISABLED';
    card.appendChild(val);
    descY += Math.max(30, val.height + 8);
  });

  // 底部分隔线
  card.appendChild(bepRect(w, 1, B, { a:0.06, x:0, y:h - FOOTER_H }));

  // 底部操作按钮（等分列）
  if (actions.length > 0) {
    var actW   = Math.floor(w / actions.length);
    var footY  = h - FOOTER_H + 12;

    actions.forEach(function(act, i) {
      var label = (typeof act === 'string') ? act : act.label;
      var isMore = (label === '更多');
      var t = bepText(label, BEP_C.primary, 14, { lh:22 });
      t.x = i * actW + Math.round((actW - t.width) / 2) - (isMore ? 8 : 0);
      t.y = footY;
      card.appendChild(t);

      if (isMore) {
        var arr = bepIcon('Line/DropDown-Arrow', 12, BEP_C.primary);
        if (arr) { arr.x = t.x + t.width + 4; arr.y = footY + 5; card.appendChild(arr); }
      }

      // 列间分隔线
      if (i < actions.length - 1) {
        card.appendChild(bepRect(1, 24, B, { a:0.06, x:(i + 1) * actW, y:h - FOOTER_H + 12 }));
      }
    });
  }

  return card;
}

/**
 * bepAddCard — 新增卡片入口（Figma真源：数据看板/卡片页）
 * opts: { width, height, title, desc }
 */
function bepAddCard(opts) {
  opts = opts || {};
  var w = opts.width || 288;
  var h = opts.height || 255;
  var card = bepFrame(w, h, { name:'AddCard', r:4, clip:true });
  card.fills = bepSolid(BEP_C.white);

  var plus = bepIcon('Line/Add', 48, B);
  if (plus) {
    plus.x = Math.round((w - 48) / 2);
    plus.y = Math.round(h / 2) - 58;
    plus.opacity = 0.65;
    card.appendChild(plus);
  }

  var title = bepText(opts.title || '新增卡片', B, 16, { style:'Medium', lh:24, a:0.85 });
  title.x = Math.round((w - title.width) / 2);
  title.y = Math.round(h / 2) - 4;
  card.appendChild(title);

  var desc = bepText(opts.desc || '卡片描述卡片描述卡片描述', B, 14, { lh:22, a:0.45 });
  desc.resize(Math.max(w - 48, 24), 22);
  desc.textAutoResize = 'NONE';
  desc.textTruncation = 'ENDING';
  desc.x = 24;
  desc.y = title.y + 32;
  desc.textAlignHorizontal = 'CENTER';
  card.appendChild(desc);

  return card;
}

// ── § 10f 指标数据卡片 MetricCard ────────────────────────────────────────────

/**
 * bepMetricCard — 指标数据卡片（Figma真源：数据看板 1/2）
 *
 * opts : {
 *   width       : 默认288
 *   height      : 默认120
 *   title       : 指标标题
 *   value       : 主数值
 *   unit        : 单位，可选
 *   iconKey     : 右侧 BeP 图标 key，可选
 *   iconColor   : 图标圆背景色，默认 BEP_C.primary
 *   iconBgAlpha : 图标圆背景透明度，默认1
 *   trendItems  : [{label, value, status:'up'|'down'|'neutral'}]
 *   miniChart   : 'bars' | 'sparkline' | 'donut'
 *   chartColor  : 迷你图主色
 * }
 *
 * 适用：数据看板 KPI 摘要、侧栏小指标、统计概览。
 * 不适用：完整折线/柱状/饼图图表容器、排行榜、表格、新闻列表。
 */
function bepMetricCard(opts) {
  opts = opts || {};
  var w = opts.width || 288;
  var h = opts.height || 120;
  var title = opts.title || '图表标题';
  var value = opts.value || '12,986';
  var unit = opts.unit || '';
  var iconKey = opts.iconKey || '';
  var iconColor = opts.iconColor || BEP_C.primary;
  var iconBgAlpha = opts.iconBgAlpha === undefined ? 1 : opts.iconBgAlpha;
  var trendItems = opts.trendItems || [];
  var miniChart = opts.miniChart || '';
  var chartColor = opts.chartColor || BEP_C.primary;
  var pad = 24;

  var card = bepFrame(w, h, { name:'MetricCard', r:4, clip:true });
  card.fills = bepSolid(BEP_C.white);

  var titleT = bepText(title, B, 14, { lh:22, a:0.45, x:pad, y:20 });
  card.appendChild(titleT);

  var valT = bepText(String(value), B, 28, { style:'Medium', lh:36, a:0.85, x:pad, y:48 });
  card.appendChild(valT);

  if (unit) {
    var unitT = bepText(String(unit), B, 14, { lh:22, a:0.45 });
    unitT.x = valT.x + valT.width + 6;
    unitT.y = 59;
    card.appendChild(unitT);
  }

  if (iconKey) {
    var iconWrap = bepRect(56, 56, iconColor, { a:iconBgAlpha, r:28, x:w - pad - 56, y:32 });
    card.appendChild(iconWrap);
    var icon = bepIcon(iconKey, 24, BEP_C.white);
    icon.x = w - pad - 40;
    icon.y = 48;
    card.appendChild(icon);
  }

  if (miniChart) {
    var chartX = w - pad - 88;
    var chartY = 42;
    if (miniChart === 'donut') {
      card.appendChild(bepRect(56, 56, chartColor, { a:0.18, r:28, x:w - pad - 56, y:32 }));
      card.appendChild(bepRect(42, 42, chartColor, { a:0.90, r:21, x:w - pad - 49, y:39 }));
      card.appendChild(bepRect(28, 28, BEP_C.white, { r:14, x:w - pad - 42, y:46 }));
    } else if (miniChart === 'sparkline') {
      var points = opts.points || [16, 30, 22, 38, 34, 46, 40, 44];
      for (var p = 0; p < points.length - 1; p++) {
        var x1 = chartX + p * 12;
        var x2 = chartX + (p + 1) * 12;
        var y1 = chartY + 44 - points[p];
        var y2 = chartY + 44 - points[p + 1];
        var len = Math.max(Math.abs(x2 - x1), 1);
        var seg = bepRect(len, 2, chartColor, { a:0.35, r:1, x:x1, y:Math.round((y1 + y2) / 2) });
        card.appendChild(seg);
      }
    } else {
      var bars = opts.bars || [18, 28, 22, 36, 30, 42];
      bars.forEach(function(bh, i) {
        card.appendChild(bepRect(8, bh, chartColor, { a:i % 2 ? 0.55 : 0.90, r:2, x:chartX + i * 13, y:chartY + 44 - bh }));
      });
    }
  }

  if (trendItems.length > 0) {
    var tx = pad;
    var ty = h - 30;
    trendItems.forEach(function(item, idx) {
      if (idx > 0) tx += 18;
      var label = bepText(item.label || '', B, 12, { lh:20, a:0.45, x:tx, y:ty });
      card.appendChild(label);
      tx += label.width + 6;
      var status = item.status || 'neutral';
      var color = status === 'up' ? BEP_C.danger : (status === 'down' ? BEP_C.success : B);
      var alpha = status === 'neutral' ? 0.65 : 1;
      var val = bepText(item.value || '', color, 12, { lh:20, a:alpha, x:tx, y:ty });
      card.appendChild(val);
      tx += val.width;
    });
  }

  return card;
}

// ── § 10g 图表容器 ChartCard ───────────────────────────────────────────────

function bepChartPalette() {
  return [
    bepHex('#006D9B'),
    bepHex('#58C76B'),
    bepHex('#FFB75E'),
    bepHex('#6EA5FF'),
    bepHex('#FF7875'),
    bepHex('#9A6DD7')
  ];
}

function bepChartLegend(items, colors, opts) {
  opts = opts || {};
  items = items || [];
  colors = colors || bepChartPalette();
  var wrap = bepFrame(opts.width || 240, 22, { name:'ChartLegend', clip:true });
  var x = 0;
  items.forEach(function(item, i) {
    var label = typeof item === 'string' ? item : item.label;
    var dot = bepRect(8, 8, colors[i % colors.length], { r:4, x:x, y:7 });
    wrap.appendChild(dot);
    var t = bepText(label || ('数据' + (i + 1)), B, 12, { lh:20, a:0.45, x:x + 12, y:1 });
    wrap.appendChild(t);
    x += 12 + t.width + 16;
  });
  return wrap;
}

function bepChartPlotBase(w, h, opts) {
  opts = opts || {};
  var plot = bepFrame(w, h, { name:'ChartPlotBase', clip:true });
  plot.fills = [];
  var gridRows = opts.gridRows === undefined ? 4 : opts.gridRows;
  if (gridRows > 0) {
    for (var i = 0; i <= gridRows; i++) {
      var y = Math.round(i * (h - 28) / gridRows) + 4;
      plot.appendChild(bepRect(w - 38, 1, B, { a:0.06, x:38, y:y }));
    }
    ['0', '25', '50', '75', '100'].forEach(function(label, i) {
      var t = bepText(label, B, 10, { lh:16, a:0.25, x:0, y:Math.round((4 - i) * (h - 28) / 4) - 2 });
      t.textAlignHorizontal = 'RIGHT';
      t.resize(28, 16);
      t.textAutoResize = 'NONE';
      plot.appendChild(t);
    });
  }
  return plot;
}

function bepChartDrawBar(plot, w, h, colors, opts) {
  opts = opts || {};
  var values = opts.values || [42, 68, 54, 86, 62, 76, 48, 70];
  var plotX = 46;
  var plotW = w - 56;
  var baseY = h - 28;
  var gap = Math.max(10, Math.floor(plotW / values.length) - 18);
  var barW = Math.max(10, Math.min(18, Math.floor((plotW - gap * (values.length - 1)) / values.length)));
  values.forEach(function(v, i) {
    var bh = Math.max(8, Math.round((baseY - 8) * v / 100));
    plot.appendChild(bepRect(barW, bh, colors[i % colors.length], {
      a:i % 2 ? 0.62 : 0.95,
      r:2,
      x:plotX + i * (barW + gap),
      y:baseY - bh
    }));
  });
}

function bepChartDrawHorizontalBar(plot, w, h, colors, opts) {
  opts = opts || {};
  var values = opts.values || [84, 72, 61, 48, 36];
  var labels = opts.labels || ['项目一', '项目二', '项目三', '项目四', '项目五'];
  var x0 = 86;
  var maxW = w - x0 - 36;
  values.forEach(function(v, i) {
    var y = 18 + i * 30;
    var label = bepText(labels[i] || ('项目' + (i + 1)), B, 12, { lh:20, a:0.45, x:0, y:y - 5 });
    plot.appendChild(label);
    plot.appendChild(bepRect(maxW, 8, B, { a:0.04, r:4, x:x0, y:y }));
    plot.appendChild(bepRect(Math.round(maxW * v / 100), 8, colors[i % colors.length], { a:0.92, r:4, x:x0, y:y }));
    var val = bepText(String(v) + '%', B, 12, { lh:20, a:0.45, x:x0 + Math.round(maxW * v / 100) + 8, y:y - 6 });
    plot.appendChild(val);
  });
}

function bepChartDrawLine(plot, w, h, colors, opts) {
  opts = opts || {};
  var values = opts.values || [36, 52, 44, 72, 64, 82, 58, 70];
  var plotX = 46;
  var plotW = w - 58;
  var baseY = h - 28;
  var step = plotW / Math.max(values.length - 1, 1);
  var prevX = 0;
  var prevY = 0;
  values.forEach(function(v, i) {
    var x = Math.round(plotX + i * step);
    var y = Math.round(baseY - (baseY - 10) * v / 100);
    if (i > 0) {
      var midX = prevX;
      var midY = y;
      plot.appendChild(bepRect(Math.max(1, x - midX), 2, colors[0], { a:0.82, r:1, x:midX, y:midY }));
      if (Math.abs(prevY - y) > 2) {
        plot.appendChild(bepRect(2, Math.abs(prevY - y), colors[0], { a:0.45, r:1, x:midX, y:Math.min(prevY, y) }));
      }
    }
    plot.appendChild(bepRect(6, 6, colors[0], { r:3, x:x - 3, y:y - 3 }));
    prevX = x;
    prevY = y;
  });
}

function bepChartDrawDonut(plot, w, h, colors, opts) {
  opts = opts || {};
  var size = Math.min(132, h - 20);
  var x = Math.round((w - size) / 2) - 38;
  var y = Math.round((h - size) / 2);
  plot.appendChild(bepRect(size, size, colors[0], { a:0.88, r:size / 2, x:x, y:y }));
  plot.appendChild(bepRect(size - 26, size - 26, colors[1], { a:0.72, r:(size - 26) / 2, x:x + 13, y:y + 13 }));
  plot.appendChild(bepRect(size - 52, size - 52, BEP_C.white, { r:(size - 52) / 2, x:x + 26, y:y + 26 }));
  var val = bepText(opts.centerValue || '68%', B, 24, { style:'Medium', lh:32, a:0.85 });
  val.x = x + Math.round((size - val.width) / 2);
  val.y = y + Math.round((size - 32) / 2);
  plot.appendChild(val);
}

function bepChartDrawGauge(plot, w, h, colors, opts) {
  opts = opts || {};
  var size = Math.min(160, h - 20);
  var x = Math.round((w - size) / 2);
  var y = Math.round((h - size) / 2) + 16;
  plot.appendChild(bepRect(size, size, B, { a:0.06, r:size / 2, x:x, y:y }));
  plot.appendChild(bepRect(size - 18, size - 18, colors[0], { a:0.78, r:(size - 18) / 2, x:x + 9, y:y + 9 }));
  plot.appendChild(bepRect(size - 48, size - 48, BEP_C.white, { r:(size - 48) / 2, x:x + 24, y:y + 24 }));
  plot.appendChild(bepRect(size, Math.round(size / 2), BEP_C.white, { x:x, y:y + Math.round(size / 2) }));
  var val = bepText(opts.centerValue || '72%', B, 24, { style:'Medium', lh:32, a:0.85 });
  val.x = x + Math.round((size - val.width) / 2);
  val.y = y + Math.round(size / 2) - 18;
  plot.appendChild(val);
}

function bepChartDrawWordCloud(plot, w, h, colors, opts) {
  opts = opts || {};
  var words = opts.words || ['物业服务', '客户满意', '商机跟进', '门店运营', '履约', '投诉处理', '能耗', '巡检'];
  var positions = [
    [42, 34, 24], [188, 24, 18], [104, 82, 20], [260, 76, 16],
    [56, 132, 16], [190, 132, 22], [326, 122, 14], [118, 168, 14]
  ];
  words.forEach(function(word, i) {
    var p = positions[i % positions.length];
    var t = bepText(word, colors[i % colors.length], p[2], { lh:p[2] + 8, a:i % 2 ? 0.72 : 0.95, x:p[0], y:p[1] });
    plot.appendChild(t);
  });
}

function bepChartDrawPlaceholder(plot, w, h, colors, opts) {
  opts = opts || {};
  var icon = bepIcon(opts.iconKey || 'Line/bar-chart', 32, colors[0]);
  icon.x = Math.round((w - 32) / 2);
  icon.y = Math.round((h - 56) / 2);
  plot.appendChild(icon);
  var text = bepText(opts.placeholder || '图表区域', B, 14, { lh:22, a:0.45 });
  text.x = Math.round((w - text.width) / 2);
  text.y = icon.y + 40;
  plot.appendChild(text);
}

/**
 * bepChartCard — 图表容器（数据看板模块）
 *
 * opts : {
 *   width, height, title, subtitle, action,
 *   tabs, activeTab,
 *   type: 'line'|'bar'|'horizontal-bar'|'donut'|'gauge'|'word-cloud'|'placeholder',
 *   legend: ['数据一', ...],
 *   metrics: [{label, value}],
 *   values, labels, words, centerValue
 * }
 *
 * 适用：数据看板完整图表模块、趋势图、分布图、横向柱状对比图的统一容器。
 * 不适用：KPI 摘要卡片（使用 bepMetricCard）、真实图表引擎实现、表格模块。
 */
function bepChartCard(opts) {
  opts = opts || {};
  var w = opts.width || 560;
  var h = opts.height || 320;
  var pad = 24;
  var title = opts.title || '图表标题';
  var type = opts.type || 'line';
  var colors = opts.colors || bepChartPalette();
  var card = bepFrame(w, h, { name:'ChartCard/' + type, r:4, clip:true });
  card.fills = bepSolid(BEP_C.white);

  var titleT = bepText(title, B, 14, { style:'Medium', lh:22, a:0.85, x:pad, y:16 });
  card.appendChild(titleT);

  if (opts.subtitle) {
    var subT = bepText(opts.subtitle, B, 12, { lh:20, a:0.45, x:pad + titleT.width + 16, y:17 });
    card.appendChild(subT);
  }

  if (opts.action) {
    var actionT = bepText(opts.action, BEP_C.primary, 14, { lh:22 });
    actionT.x = w - pad - actionT.width;
    actionT.y = 16;
    card.appendChild(actionT);
  }

  card.appendChild(bepRect(w - pad * 2, 1, B, { a:0.06, x:pad, y:48 }));

  var contentY = 64;
  if (opts.tabs && opts.tabs.length) {
    var tabBar = bepCardTabs(opts.tabs, opts.activeTab || 0, w, { inset:pad });
    tabBar.y = 48;
    card.appendChild(tabBar);
    contentY = 112;
  }

  if (opts.legend && opts.legend.length) {
    var legend = bepChartLegend(opts.legend, colors, { width:w - pad * 2 });
    legend.x = pad;
    legend.y = contentY;
    card.appendChild(legend);
    contentY += 30;
  }

  var metrics = opts.metrics || [];
  var metricW = 0;
  if (metrics.length) {
    metricW = Math.min(156, Math.floor((w - pad * 2) * 0.28));
    metrics.forEach(function(item, i) {
      var my = contentY + i * 48;
      var val = bepText(item.value || '0', B, 24, { style:'Medium', lh:32, a:0.85, x:w - pad - metricW, y:my });
      card.appendChild(val);
      var label = bepText(item.label || '指标', B, 12, { lh:20, a:0.45, x:w - pad - metricW, y:my + 30 });
      card.appendChild(label);
    });
  }

  var plotW = w - pad * 2 - metricW - (metricW ? 24 : 0);
  var plotH = Math.max(120, h - contentY - 24);
  var plot = bepChartPlotBase(plotW, plotH, { gridRows:type === 'horizontal-bar' ? 0 : 4 });
  plot.name = 'ChartPlot/' + type;
  plot.x = pad;
  plot.y = contentY;
  card.appendChild(plot);

  if (type === 'bar') {
    bepChartDrawBar(plot, plotW, plotH, colors, opts);
  } else if (type === 'horizontal-bar') {
    bepChartDrawHorizontalBar(plot, plotW, plotH, colors, opts);
  } else if (type === 'donut') {
    bepChartDrawDonut(plot, plotW, plotH, colors, opts);
  } else if (type === 'gauge') {
    bepChartDrawGauge(plot, plotW, plotH, colors, opts);
  } else if (type === 'word-cloud') {
    bepChartDrawWordCloud(plot, plotW, plotH, colors, opts);
  } else if (type === 'placeholder') {
    bepChartDrawPlaceholder(plot, plotW, plotH, colors, opts);
  } else {
    bepChartDrawLine(plot, plotW, plotH, colors, opts);
  }

  return card;
}

// ── § 10h 看板表格 / 排行榜 Dashboard Modules ─────────────────────────────

function bepDashboardModuleHeader(card, opts, w, pad) {
  opts = opts || {};
  pad = pad || 24;
  var titleT = bepText(opts.title || '模块标题', B, 14, { style:'Medium', lh:22, a:0.85, x:pad, y:16 });
  card.appendChild(titleT);

  if (opts.subtitle) {
    var subT = bepText(opts.subtitle, B, 12, { lh:20, a:0.45, x:pad + titleT.width + 16, y:17 });
    card.appendChild(subT);
  }

  if (opts.action) {
    var actionT = bepText(opts.action, BEP_C.primary, 14, { lh:22 });
    actionT.x = w - pad - actionT.width;
    actionT.y = 16;
    card.appendChild(actionT);
  }

  card.appendChild(bepRect(w - pad * 2, 1, B, { a:0.06, x:pad, y:48 }));
}

function bepDashboardContentY(card, opts, w, pad) {
  var contentY = 64;
  if (opts.tabs && opts.tabs.length) {
    var tabBar = bepCardTabs(opts.tabs, opts.activeTab || 0, w, { inset:pad });
    tabBar.y = 48;
    card.appendChild(tabBar);
    contentY = 112;
  }
  return contentY;
}

function bepDashboardNormalizeCols(cols, tableW) {
  cols = cols || [];
  if (!cols.length) {
    cols = [
      { label:'名称', key:'name' },
      { label:'数量', key:'value', align:'right' },
      { label:'占比', key:'rate', align:'right' }
    ];
  }
  var fixed = 0;
  var flexCount = 0;
  var out = cols.map(function(col) {
    var w = col.w || col.width || 0;
    if (w) fixed += w;
    else flexCount++;
    return {
      label: col.label || col.title || '',
      key: col.key,
      w: w,
      align: col.align || 'left'
    };
  });
  var flexW = flexCount ? Math.floor(Math.max(tableW - fixed, flexCount * 80) / flexCount) : 0;
  var sum = 0;
  out.forEach(function(col) {
    if (!col.w) col.w = flexW;
    sum += col.w;
  });
  if (out.length && sum !== tableW) out[out.length - 1].w += tableW - sum;
  return out;
}

function bepDashboardTableCells(row, cols) {
  if (Array.isArray(row)) {
    return row.map(function(item) {
      if (item && typeof item === 'object' && item.content !== undefined) return item;
      return { content:String(item === undefined ? '-' : item) };
    });
  }
  row = row || {};
  return cols.map(function(col) {
    var val = row[col.key] !== undefined ? row[col.key] : row[col.label];
    return { content:String(val === undefined || val === null || val === '' ? '-' : val), align:col.align };
  });
}

/**
 * bepDashboardTableCard — 看板表格模块
 *
 * opts : { width, height, title, subtitle, action, tabs, activeTab, cols, rows, size }
 *
 * 适用：数据看板中的表格型模块、Top 明细、小型统计表。
 * 内部必须复用 bepTableHeader / bepTableRow，不能手写表头和单元格。
 */
function bepDashboardTableCard(opts) {
  opts = opts || {};
  var w = opts.width || 560;
  var h = opts.height || 320;
  var pad = 24;
  var card = bepFrame(w, h, { name:'DashboardTableCard', r:4, clip:true });
  card.fills = bepSolid(BEP_C.white);
  bepDashboardModuleHeader(card, opts, w, pad);
  var contentY = bepDashboardContentY(card, opts, w, pad);

  var tableW = w - pad * 2;
  var cols = bepDashboardNormalizeCols(opts.cols, tableW);
  var rows = opts.rows || [
    { name:'项目一', value:'12,986', rate:'36%' },
    { name:'项目二', value:'8,621', rate:'24%' },
    { name:'项目三', value:'6,388', rate:'18%' },
    { name:'项目四', value:'3,209', rate:'9%' }
  ];
  var size = opts.size || 'mini';
  var spec = bepTableSpec({ size:size });
  var maxRows = Math.max(0, Math.floor((h - contentY - pad - spec.h) / spec.h));
  var visibleRows = rows.slice(0, opts.maxRows || maxRows || rows.length);

  var header = bepTableHeader(cols, tableW, { size:size });
  header.x = pad;
  header.y = contentY;
  card.appendChild(header);

  visibleRows.forEach(function(row, idx) {
    var cells = bepDashboardTableCells(row, cols);
    var rowNode = bepTableRow(cells, cols, tableW, null, { size:size });
    rowNode.x = pad;
    rowNode.y = contentY + spec.h + idx * spec.h;
    card.appendChild(rowNode);
  });

  if (!visibleRows.length) {
    var empty = bepEmptyState(tableW);
    empty.x = pad;
    empty.y = contentY + spec.h;
    card.appendChild(empty);
  }

  return card;
}

function bepRankBadge(rank) {
  var color = rank === 1 ? BEP_C.danger : (rank === 2 ? BEP_C.warning : (rank === 3 ? BEP_C.primary : B));
  var alpha = rank <= 3 ? 1 : 0.06;
  var badge = bepFrame(22, 22, { name:'RankBadge/' + rank, r:11, clip:true });
  badge.fills = bepSolid(color, alpha);
  var t = bepText(String(rank), rank <= 3 ? BEP_C.white : B, 12, { style:'Medium', lh:20, a:rank <= 3 ? 1 : 0.45 });
  t.x = Math.round((22 - t.width) / 2);
  t.y = 1;
  badge.appendChild(t);
  return badge;
}

function bepRankListRow(item, rank, w, opts) {
  opts = opts || {};
  var rowH = opts.rowHeight || 42;
  var row = bepFrame(w, rowH, { name:'RankRow/' + rank, clip:true });
  row.fills = [];
  row.appendChild(bepRect(w, 1, B, { a:0.06, x:0, y:rowH - 1 }));

  var badge = bepRankBadge(rank);
  badge.x = 0;
  badge.y = Math.round((rowH - 22) / 2);
  row.appendChild(badge);

  var label = bepTableText(item.label || item.name || ('项目' + rank), B, Math.max(80, w - 170), { a:0.65 });
  label.x = 34;
  label.y = Math.round((rowH - 22) / 2);
  row.appendChild(label);

  var valueText = item.value === undefined ? '' : String(item.value);
  if (valueText) {
    var val = bepText(valueText, B, 14, { lh:22, a:0.85 });
    val.x = w - val.width;
    val.y = Math.round((rowH - 22) / 2);
    row.appendChild(val);
  }

  if (item.rate !== undefined || item.percent !== undefined) {
    var rate = Number(item.rate !== undefined ? item.rate : item.percent);
    if (!isNaN(rate)) {
      var barW = Math.min(120, Math.max(72, Math.floor(w * 0.24)));
      var barX = w - barW - (valueText ? 64 : 0);
      row.appendChild(bepRect(barW, 6, B, { a:0.04, r:3, x:barX, y:Math.round((rowH - 6) / 2) }));
      row.appendChild(bepRect(Math.round(barW * Math.max(0, Math.min(rate, 100)) / 100), 6, BEP_C.primary, { a:0.90, r:3, x:barX, y:Math.round((rowH - 6) / 2) }));
    }
  }

  return row;
}

/**
 * bepRankListCard — 排行榜模块
 *
 * opts : { width, height, title, subtitle, action, tabs, activeTab, items, showProgress }
 *
 * 适用：数据看板中的列表型排行、Top N 榜单。
 * 不适用：横向柱状排行图（使用 bepChartCard type:'horizontal-bar'）。
 */
function bepRankListCard(opts) {
  opts = opts || {};
  var w = opts.width || 360;
  var h = opts.height || 320;
  var pad = 24;
  var card = bepFrame(w, h, { name:'RankListCard', r:4, clip:true });
  card.fills = bepSolid(BEP_C.white);
  bepDashboardModuleHeader(card, opts, w, pad);
  var contentY = bepDashboardContentY(card, opts, w, pad);

  var items = opts.items || [
    { label:'项目名称一', value:'12,986', rate:92 },
    { label:'项目名称二', value:'8,621', rate:76 },
    { label:'项目名称三', value:'6,388', rate:61 },
    { label:'项目名称四', value:'3,209', rate:48 },
    { label:'项目名称五', value:'2,106', rate:36 }
  ];
  var rowW = w - pad * 2;
  var rowH = opts.rowHeight || 42;
  var maxRows = Math.max(0, Math.floor((h - contentY - pad) / rowH));
  items.slice(0, opts.maxRows || maxRows || items.length).forEach(function(item, idx) {
    var row = bepRankListRow(item, idx + 1, rowW, { rowHeight:rowH });
    row.x = pad;
    row.y = contentY + idx * rowH;
    card.appendChild(row);
  });

  return card;
}

// ── § 10b 描述列表（详情信息展示）──────────────────────────────────────────

function makeDescValueText(chars, color, opacity, maxW, wrap) {
  var t = bepTableText(chars || '', color, maxW, { a:opacity });
  if (wrap) {
    t.textAutoResize = 'HEIGHT';
    t.textTruncation = 'DISABLED';
    t.resize(Math.max(maxW, 8), 22);
  }
  return t;
}

function bepDescLink(label, opts) {
  opts = opts || {};
  var text = (typeof label === 'object') ? (label.label || label.name || label.url || '') : String(label || '');
  var maxW = opts.maxW || 240;
  var link = bepFrame(maxW, 22, { name:'DescLink/' + text, clip:false });
  link.fills = [];

  var measure = bepText(text, BEP_C.primary, 14, { lh:22 });
  var textW = Math.min(maxW, measure.width);
  measure.remove();
  var t = makeDescValueText(text, BEP_C.primary, 1, maxW, false);
  t.name = 'LinkText';
  t.x = 0;
  t.y = 0;
  link.appendChild(t);
  link.resize(Math.max(1, textW), 22);
  return link;
}

function bepDescTags(tags, opts) {
  opts = opts || {};
  tags = tags || [];
  var maxW = opts.maxW || 240;
  var wrap = bepFrame(maxW, 22, { name:'DescTags', clip:false });
  wrap.fills = [];

  var x = 0;
  var y = 0;
  var rowH = 22;
  var maxLineW = 0;
  var gap = opts.gap || 8;
  tags.forEach(function(tagDef) {
    var label = (typeof tagDef === 'string') ? tagDef : (tagDef.label || tagDef.value || '');
    var type = (typeof tagDef === 'string') ? 'info' : (tagDef.type || 'info');
    var style = (typeof tagDef === 'string') ? 'outline' : (tagDef.style || 'outline');
    var tag = bepTag(label, type, style);
    if (x > 0 && x + tag.width > maxW) {
      maxLineW = Math.max(maxLineW, x - gap);
      x = 0;
      y += rowH + 8;
    }
    tag.x = x;
    tag.y = y;
    wrap.appendChild(tag);
    x += tag.width + gap;
  });
  maxLineW = Math.max(maxLineW, x > 0 ? x - gap : 0);
  wrap.resize(Math.max(1, Math.min(maxW, maxLineW)), Math.max(rowH, y + rowH));
  return wrap;
}

function bepDescInlineValue(opts) {
  opts = opts || {};
  var text = opts.value || '';
  var tags = opts.tags || [];
  var maxW = opts.maxW || 240;
  var wrap = bepFrame(maxW, 22, { name:'DescInlineValue', clip:false });
  wrap.fills = [];

  var x = 0;
  if (text) {
    var textMaxW = Math.max(8, maxW - 8);
    var measure = bepText(text, B, 14, { lh:22 });
    var measuredTextW = Math.min(textMaxW, measure.width);
    measure.remove();
    var txt = makeDescValueText(text, B, 0.85, textMaxW, false);
    txt.name = 'ValueText';
    txt.x = 0;
    txt.y = 0;
    wrap.appendChild(txt);
    x = measuredTextW;
  }

  if (tags.length) {
    var tagNode = bepDescTags(tags, { maxW: Math.max(8, maxW - x - (x ? 8 : 0)) });
    tagNode.name = 'ValueTags';
    tagNode.x = x ? x + 8 : 0;
    tagNode.y = 0;
    wrap.appendChild(tagNode);
    x = tagNode.x + tagNode.width;
  }

  var h = 22;
  wrap.children.forEach(function(n) { h = Math.max(h, n.y + n.height); });
  wrap.resize(Math.max(1, Math.min(maxW, x)), h);
  return wrap;
}

function bepDescLinks(links, opts) {
  opts = opts || {};
  links = links || [];
  var maxW = opts.maxW || 240;
  var wrap = bepFrame(maxW, 22, { name:'DescLinks', clip:false });
  wrap.fills = [];

  var x = 0;
  var y = 0;
  var gap = opts.gap || 16;
  var maxLineW = 0;
  links.forEach(function(linkDef) {
    var link = bepDescLink(linkDef, { maxW:maxW });
    if (x > 0 && x + link.width > maxW) {
      maxLineW = Math.max(maxLineW, x - gap);
      x = 0;
      y += 30;
    }
    link.x = x;
    link.y = y;
    wrap.appendChild(link);
    x += link.width + gap;
  });
  maxLineW = Math.max(maxLineW, x > 0 ? x - gap : 0);
  wrap.resize(Math.max(1, Math.min(maxW, maxLineW)), Math.max(22, y + 22));
  return wrap;
}

function bepDescAttachments(files, opts) {
  opts = opts || {};
  files = files || [];
  var maxW = opts.maxW || 480;
  var wrap = bepFrame(maxW, 22, { name:'DescAttachments', clip:false });
  wrap.fills = [];

  var y = 0;
  files.forEach(function(fileDef, i) {
    var name = (typeof fileDef === 'string') ? fileDef : (fileDef.name || fileDef.label || '');
    var size = (typeof fileDef === 'string') ? '' : (fileDef.size || '');
    var row = bepFrame(maxW, 22, { name:'Attachment/' + name, clip:false });
    row.fills = [];

    var ico = bepIcon('Line/Paperclip', 16, B);
    if (ico) {
      ico.opacity = 0.45;
      ico.x = 0;
      ico.y = 3;
      row.appendChild(ico);
    }

    var titleMaxW = Math.max(48, maxW - 16 - 8 - (size ? 72 : 0));
    var title = makeDescValueText(name, BEP_C.primary, 1, titleMaxW, false);
    title.name = 'AttachmentName';
    title.x = 24;
    title.y = 0;
    row.appendChild(title);

    if (size) {
      var sizeText = makeDescValueText(size, B, 0.45, 64, false);
      sizeText.name = 'AttachmentSize';
      sizeText.x = 24 + titleMaxW + 8;
      sizeText.y = 0;
      row.appendChild(sizeText);
    }

    row.y = y;
    wrap.appendChild(row);
    y += i < files.length - 1 ? 30 : 22;
  });
  wrap.resize(maxW, Math.max(22, y));
  return wrap;
}

function bepDescMedia(items, opts) {
  opts = opts || {};
  items = items || [];
  var thumbW = opts.thumbW || 80;
  var thumbH = opts.thumbH || 60;
  var gap = opts.gap || 8;
  var maxW = opts.maxW || 480;
  var wrap = bepFrame(maxW, thumbH, { name:'DescMedia', clip:false });
  wrap.fills = [];

  var x = 0;
  var y = 0;
  var maxLineW = 0;
  items.forEach(function(mediaDef) {
    var label = (typeof mediaDef === 'string') ? mediaDef : (mediaDef.label || mediaDef.name || '');
    var type = (typeof mediaDef === 'string') ? 'image' : (mediaDef.type || 'image');
    if (x > 0 && x + thumbW > maxW) {
      maxLineW = Math.max(maxLineW, x - gap);
      x = 0;
      y += thumbH + gap;
    }

    var item = bepFrame(thumbW, thumbH, { name:(type === 'video' ? 'Video/' : 'Image/') + label, r:4, clip:true });
    item.fills = bepSolid(B, 0.04);
    item.strokes = bepSolid(B, 0.10);
    item.strokeWeight = 1;
    item.strokeAlign = 'INSIDE';

    var iconKey = type === 'video' ? 'Fill/play' : 'Line/camera';
    var ico = bepIcon(iconKey, type === 'video' ? 18 : 20, B);
    if (ico) {
      ico.opacity = type === 'video' ? 0.65 : 0.35;
      ico.x = Math.round((thumbW - ico.width) / 2);
      ico.y = Math.round((thumbH - ico.height) / 2);
      item.appendChild(ico);
    }

    item.x = x;
    item.y = y;
    wrap.appendChild(item);
    x += thumbW + gap;
  });
  maxLineW = Math.max(maxLineW, x > 0 ? x - gap : 0);
  wrap.resize(Math.max(1, Math.min(maxW, maxLineW)), Math.max(thumbH, y + thumbH));
  return wrap;
}

function bepDescValueNode(item, maxW, wrapText) {
  item = item || {};
  if (item.node) return item.node;
  if (item.attachments) return bepDescAttachments(item.attachments, { maxW:maxW });
  if (item.media) return bepDescMedia(item.media, { maxW:maxW });
  if (item.links) return bepDescLinks(item.links, { maxW:maxW });
  if (item.link) return bepDescLinks([item.link], { maxW:maxW });
  if (item.tags && item.value) return bepDescInlineValue({ value:item.value, tags:item.tags, maxW:maxW });
  if (item.tags) return bepDescTags(item.tags, { maxW:maxW });

  var valColor = item.color || B;
  var valOpacity = item.color ? 1 : 0.85;
  return makeDescValueText(item.value || '', valColor, valOpacity, maxW, wrapText);
}

/**
 * 描述列表（详情页只读信息）
 * sections: [
 *   { title:'系统信息', items:[
 *      {label:'系统编码', value:'MALL_PLATFORM'},
 *      {label:'系统名称', value:'商城运营平台'},
 *      {label:'系统描述', value:'...', long:true}
 *   ]}
 * ]
   * opts: { columns, rowGap, sectionGapTop, sectionGapBottom, titleGap, longTextThreshold }
 */
function bepDescriptions(sections, width, opts) {
  opts = opts || {};
  width = width || 1152;
  var columns = opts.columns || 3;
  var rowGap = opts.rowGap || 16;
  var sectionGapTop = opts.sectionGapTop || 24;
  var sectionGapBottom = opts.sectionGapBottom || 24;
  var dividerOpacity = opts.dividerOpacity !== undefined ? opts.dividerOpacity : 0.10;
  var titleGap = opts.titleGap || 24;
  var longTextThreshold = opts.longTextThreshold || 30;
  var colW = Math.floor(width / columns);
  var valueGap = 16;

  function isLongDesc(item) {
    if (!item) return false;
    if (item.long === true || item.type === 'long') return true;
    if (item.span && item.span >= columns) return true;
    if (item.node) return false;
    if (item.attachments || item.media || item.links || item.link || item.tags) return false;
    var v = String(item.value || '');
    return v.length > longTextThreshold;
  }

  function normalizeDescRows(sec) {
    var src = [];
    if (sec.items) {
      src = sec.items;
    } else {
      var rawRows = sec.rows || [];
      for (var rr = 0; rr < rawRows.length; rr++) {
        var rawRow = rawRows[rr] || [];
        for (var ri = 0; ri < rawRow.length; ri++) src.push(rawRow[ri]);
      }
    }
    var rows = [];
    var current = [];
    var used = 0;
    for (var ii = 0; ii < src.length; ii++) {
      var item = src[ii] || {};
      if (isLongDesc(item)) {
        if (current.length) {
          rows.push(current);
          current = [];
          used = 0;
        }
        item.span = columns;
        rows.push([item]);
      } else {
        var span = item.span || 1;
        if (span < 1) span = 1;
        if (span > columns) span = columns;
        item.span = span;
        if (used + span > columns && current.length) {
          rows.push(current);
          current = [];
          used = 0;
        }
        current.push(item);
        used += span;
        if (used >= columns) {
          rows.push(current);
          current = [];
          used = 0;
        }
      }
    }
    if (current.length) rows.push(current);
    return rows;
  }

  var wrap = bepFrame(width, 1, { name:'Descriptions', clip:false });
  wrap.fills = [];
  var y = 0;

  for (var s = 0; s < sections.length; s++) {
    var sec = sections[s];
    var sectionName = sec.title || ('Section' + (s + 1));
    var section = bepFrame(width, 1, { name:'Section/' + sectionName, clip:false });
    section.fills = [];
    section.x = 0;
    section.y = y;
    wrap.appendChild(section);

    var localY = 0;
    var title = bepText(sec.title || '', B, 16, { style:'Medium', lh:24, a:0.85 });
    title.name = 'SectionTitle';
    title.x = 0;
    title.y = localY;
    section.appendChild(title);
    localY = localY + 24 + titleGap;

    var rows = normalizeDescRows(sec);
    for (var r = 0; r < rows.length; r++) {
      var row = rows[r] || [];
      var maxRowH = 22;
      var colIndex = 0;
      var rowNo = (r + 1 < 10 ? '0' : '') + (r + 1);
      var rowFrame = bepFrame(width, 22, { name:'Row/' + rowNo, clip:false });
      rowFrame.fills = [];
      rowFrame.x = 0;
      rowFrame.y = localY;
      section.appendChild(rowFrame);

      for (var c = 0; c < row.length; c++) {
        var item = row[c] || {};
        var span = item.span || 1;
        if (span < 1) span = 1;
        if (span > columns) span = columns;
        var x = colIndex * colW;
        var itemW = colW * span;
        var itemName = item.label || ('Item' + (c + 1));
        var itemFrame = bepFrame(itemW, 22, { name:'Item/' + itemName, clip:false });
        itemFrame.fills = [];
        itemFrame.x = x;
        itemFrame.y = 0;
        rowFrame.appendChild(itemFrame);

        var label = item.label || '';
        if (label && label.slice(-1) !== ':' && label.slice(-1) !== '：') label = label + ':';
        var lbl = bepText(label, B, 14, { lh:22, a:0.45 });
        lbl.name = 'Label';
        lbl.x = 0;
        lbl.y = 0;
        itemFrame.appendChild(lbl);

        var valueMaxW = itemW - lbl.width - valueGap - 16;
        var shouldWrap = span >= columns || item.long === true || item.type === 'long';
        var valNode = bepDescValueNode(item, valueMaxW, shouldWrap);
        valNode.name = 'Value';
        valNode.x = lbl.width + valueGap;
        valNode.y = 0;
        itemFrame.appendChild(valNode);
        itemFrame.resize(itemW, Math.max(22, valNode.height || 22));
        maxRowH = Math.max(maxRowH, valNode.height || 22);
        colIndex += span;
      }
      rowFrame.resize(width, maxRowH);
      localY = localY + maxRowH + rowGap;
    }
    localY = localY - rowGap;
    section.resize(width, localY);
    y = y + section.height;
    if (s < sections.length - 1) {
      var divider = bepRect(width, 1, B, { a:dividerOpacity, x:0, y:y + sectionGapTop, name:'SectionDivider' });
      wrap.appendChild(divider);
      y = y + sectionGapTop + 1 + sectionGapBottom;
    }
  }
  wrap.resize(width, y);
  return wrap;
}

// ── § 11  时间轴（Figma真源：3.DataDisplay/9.Timeline时间轴）───────────────

/**
 * bepTimeline — 时间顺序记录展示
 *
 * items: [{
 *   title, time, desc,
 *   status: 'success' | 'error' | 'processing' | 'end' | 'default',
 *   lineType: 'solid' | 'dashed'
 * }]
 * opts: { width, variant, itemGap, descBg }
 *
 * variant:
 *   basic       标题 + 时间
 *   description 标题 + 时间 + 描述内容块
 *
 * 规格（Figma真源 node 700:27656）：
 *   点：8×8，x=0，y=7；内容列 x=24
 *   标题：14px，lh=22；basic Regular，description Medium；黑 85%
 *   时间：12px，lh=20，黑 45%，y=22
 *   描述：14px，lh=22，黑 65%，背景黑 4%，r=2，内边距 16，y=50
 *   项间距：24px；连接线黑 10%，支持实线/虚线
 */
function bepTimeline(items, opts) {
  opts = opts || {};
  items = items || [];

  var width = opts.width || 624;
  var variant = opts.variant || 'description';
  var itemGap = opts.itemGap !== undefined ? opts.itemGap : 24;
  var dotSize = 8;
  var textX = 24;
  var titleH = 22;
  var timeH = 20;
  var descPad = 16;
  var descTop = 50;
  var descLineH = 22;
  var descBg = opts.descBg || B;
  var descBgA = opts.descBgA !== undefined ? opts.descBgA : 0.04;

  function timelineStatusCfg(status) {
    if (status === 'error' || status === 'danger' || status === 'reject') {
      return { fill:BEP_C.danger, stroke:null, strokeA:0, titleA:0.85, timeA:0.45 };
    }
    if (status === 'processing' || status === 'current' || status === 'pending') {
      return { fill:BEP_C.white, stroke:BEP_C.primary, strokeA:1, titleA:0.85, timeA:0.45 };
    }
    if (status === 'end' || status === 'disabled' || status === 'finish') {
      return { fill:B, fillA:0.25, stroke:null, strokeA:0, titleA:0.45, timeA:0.45 };
    }
    return { fill:BEP_C.primary, stroke:null, strokeA:0, titleA:0.85, timeA:0.45 };
  }

  function estimateLines(text, maxW) {
    var chars = Array.from(String(text || '')).length;
    var perLine = Math.max(8, Math.floor(maxW / 14));
    return Math.max(1, Math.ceil(chars / perLine));
  }

  function appendLine(parent, x, y, h, lineType) {
    if (h <= 0) return;
    if (lineType === 'dashed') {
      var dashY = y;
      while (dashY < y + h) {
        var segH = Math.min(6, y + h - dashY);
        parent.appendChild(bepRect(1, segH, B, { a:0.10, x:x + 0.5, y:dashY, name:'TimelineLineDash' }));
        dashY += 12;
      }
    } else {
      parent.appendChild(bepRect(2, h, B, { a:0.10, x:x, y:y, name:'TimelineLine' }));
    }
  }

  var wrap = bepFrame(width, 1, { name:'Timeline', clip:false });
  wrap.fills = [];

  var y = 0;
  for (var i = 0; i < items.length; i++) {
    var data = items[i] || {};
    var isDescription = variant === 'description' || data.desc;
    var itemW = width;
    var textW = Math.max(48, itemW - textX);
    var descW = textW;
    var descInnerW = Math.max(48, descW - descPad * 2);
    var descLines = isDescription && data.desc ? estimateLines(data.desc, descInnerW) : 0;
    var descBoxH = isDescription && data.desc ? Math.max(54, descPad * 2 + descLines * descLineH) : 0;
    var itemH = isDescription ? (data.desc ? descTop + descBoxH : 50) : 42;

    var item = bepFrame(itemW, itemH, { name:'Timeline/Item/' + (data.title || (i + 1)), clip:false });
    item.fills = [];
    item.x = 0;
    item.y = y;
    wrap.appendChild(item);

    if (i < items.length - 1) {
      appendLine(wrap, 3, y + 15, itemH + itemGap - 15, data.lineType || 'solid');
    }

    var cfg = timelineStatusCfg(data.status || 'default');
    var dot = bepFrame(dotSize, dotSize, { name:'TimelineDot', r:dotSize / 2, clip:true });
    dot.x = 0;
    dot.y = 7;
    dot.fills = bepSolid(cfg.fill, cfg.fillA !== undefined ? cfg.fillA : 1);
    if (cfg.stroke) {
      dot.strokes = bepSolid(cfg.stroke, cfg.strokeA);
      dot.strokeWeight = 1;
      dot.strokeAlign = 'INSIDE';
    }
    item.appendChild(dot);

    var titleStyle = isDescription ? 'Medium' : 'Regular';
    var title = bepTableText(data.title || '', B, textW, { style:titleStyle, a:cfg.titleA });
    title.name = 'TimelineTitle';
    title.x = textX;
    title.y = 0;
    item.appendChild(title);

    if (data.time) {
      var time = bepTableText(data.time, B, textW, { a:cfg.timeA });
      time.name = 'TimelineTime';
      time.fontSize = 12;
      time.lineHeight = { value:timeH, unit:'PIXELS' };
      time.resize(textW, timeH);
      time.x = textX;
      time.y = titleH;
      item.appendChild(time);
    }

    if (isDescription && data.desc) {
      var descBox = bepFrame(descW, descBoxH, { name:'TimelineDescription', r:2, clip:false });
      descBox.fills = bepSolid(descBg, descBgA);
      descBox.x = textX;
      descBox.y = descTop;
      item.appendChild(descBox);

      var descText = bepTableText(data.desc, B, descInnerW, { a:0.65 });
      descText.name = 'TimelineDescriptionText';
      descText.textAutoResize = 'HEIGHT';
      descText.textTruncation = 'DISABLED';
      descText.resize(descInnerW, descLineH);
      descText.x = descPad;
      descText.y = descPad;
      descBox.appendChild(descText);
      descBox.resize(descW, Math.max(descBoxH, descText.y + descText.height + descPad));
      item.resize(itemW, descBox.y + descBox.height);
    }

    y += item.height + (i < items.length - 1 ? itemGap : 0);
  }

  wrap.resize(width, Math.max(1, y));
  return wrap;
}

// ── § 12  步骤条（Figma实测：基础/带描述/竖式，3态）────────────────────────────

/**
 * bepSteps — 步骤条
 *
 * steps      : [{title, desc}] 步骤列表
 * currentIdx : 当前步骤索引（0-based）；< currentIdx = 已完成，> = 待处理
 * totalWidth : 总宽（默认 1152）
 * opts       : { variant:'basic'|'description'|'vertical' }
 *
 * 三种状态（Figma实测）：
 *   待处理：白底圆圈+灰色边框，数字 rgba(0,0,0,0.25)，标题/描述 65%/45%
 *   当前  ：主色实心圆，白色数字，标题 Medium 85%，描述 85%
 *   已完成：主色实心圆，白色 Fill/Success ✓，标题 65%，描述 45%
 *
 * 规格：基础 h=54，带描述 h=78，圆圈 24×24，标题 y=32 14px，描述 y=58 12px
 *       连接线 y=12 h=1px rgba(0,0,0,0.10)，已完成步骤连接线用主色
 */
function bepSteps(steps, currentIdx, totalWidth, opts) {
  steps      = steps      || [];
  currentIdx = (currentIdx !== undefined) ? currentIdx : 0;
  if (typeof totalWidth === 'object' && totalWidth !== null) {
    opts = totalWidth;
    totalWidth = undefined;
  }
  opts = opts || {};
  totalWidth = totalWidth || 1152;
  if (!steps.length) return bepFrame(totalWidth, 0, { name:'Steps', clip:false });

  var variant = opts.variant || (steps.some(function(s) { return s && s.desc; }) ? 'description' : 'basic');
  var isVertical = variant === 'vertical';
  var showDesc = variant === 'description' || variant === 'vertical';

  var STEP_H = showDesc ? 78 : 54;
  var CIRC   = 24;
  var stepW  = Math.floor(totalWidth / steps.length);
  var vGap   = 24;
  var wrapH  = isVertical ? (steps.length * STEP_H + (steps.length - 1) * vGap) : STEP_H;

  var wrap = bepFrame(totalWidth, wrapH, { name:isVertical ? 'StepsVertical' : 'Steps', clip:false });
  wrap.fills = [];

  steps.forEach(function(step, i) {
    var isLast  = (i === steps.length - 1);
    var w       = isVertical ? totalWidth : (isLast ? (totalWidth - stepW * (steps.length - 1)) : stepW);
    var state   = i < currentIdx ? 'done' : (i === currentIdx ? 'current' : 'pending');

    var item = bepFrame(w, STEP_H, { name:'Step' + (i+1), clip:false });
    item.fills = [];
    item.x = isVertical ? 0 : i * stepW;
    item.y = isVertical ? i * (STEP_H + vGap) : 0;

    // 连接线（除最后一步）
    if (!isLast) {
      var divColor = (state === 'done') ? BEP_C.primary : B;
      var divA     = (state === 'done') ? 1 : 0.10;
      if (isVertical) {
        item.appendChild(bepRect(1, STEP_H + vGap - CIRC, divColor, { a:divA, x:Math.round(CIRC/2), y:CIRC }));
      } else {
        item.appendChild(bepRect(w - CIRC, 1, divColor, { a:divA, x:CIRC, y:Math.round(CIRC/2) }));
      }
    }

    // 圆圈 24×24
    var circle = bepFrame(CIRC, CIRC, { name:'Circle', clip:true });
    circle.cornerRadius = CIRC / 2;
    circle.x = 0; circle.y = 0;

    if (state === 'done') {
      circle.fills = bepSolid(BEP_C.primary);
      var ico = bepIcon('Fill/Success', 16, BEP_C.white);
      if (ico) { ico.x = 4; ico.y = 4; circle.appendChild(ico); }
    } else if (state === 'current') {
      circle.fills = bepSolid(BEP_C.primary);
      var nt = bepText(String(i + 1), BEP_C.white, 14, { style:'Medium', lh:22 });
      nt.x = Math.round((CIRC - nt.width) / 2); nt.y = 1;
      circle.appendChild(nt);
    } else {
      circle.fills = bepSolid(BEP_C.white);
      circle.strokes = bepSolid(B, 0.15);
      circle.strokeWeight = 1; circle.strokeAlign = 'INSIDE';
      var nt = bepText(String(i + 1), B, 14, { style:'Medium', lh:22, a:0.25 });
      nt.x = Math.round((CIRC - nt.width) / 2); nt.y = 1;
      circle.appendChild(nt);
    }
    item.appendChild(circle);

    // 标题
    var tStyle = (state === 'current') ? 'Medium' : 'Regular';
    var tA     = (state === 'current') ? 0.85 : 0.65;
    var textX = isVertical ? 36 : 0;
    var titleT = bepText(step.title || '', B, 14, { style:tStyle, lh:22, a:tA, x:textX, y:isVertical ? 1 : 32 });
    item.appendChild(titleT);

    // 描述（可选）
    if (showDesc && step.desc) {
      var dA    = (state === 'current') ? 0.85 : 0.45;
      var descT = bepText(step.desc, B, 12, { lh:20, a:dA, x:textX, y:isVertical ? 27 : 58 });
      item.appendChild(descT);
    }

    wrap.appendChild(item);
  });

  return wrap;
}

// ── § 12  全局提示 Message（Figma实测：5.FeedBack/1.Message全局提示）──────────

/**
 * bepMessage — 浮动全局提示（信息/成功/失败/加载中）
 *
 * text : 提示文字
 * type : 'info'（默认）| 'success' | 'error' | 'danger' | 'loading'
 *
 * 规格（Figma实测）：
 *   h=40，r=2，左padding=16，icon 16×16 at x=16 y=12，text x=40 y=9
 *   宽度由内容自适应；info/success/error 最小宽度 120px
 *   loading 为白底悬浮卡片，最小宽度 106px，带阴影
 *
 * 使用方式：返回Frame节点，调用方负责定位（通常水平居中、置于页面顶部）
 */
function bepMessage(text, type) {
  type = type || 'info';
  if (type === 'danger') type = 'error';

  var TYPES = {
    info:    { bg: bepHex('E6F0F5'), bd: bepHex('CCE2EB'), icon: 'Fill/Tips',    minW:120 },
    success: { bg: bepHex('EBF8EC'), bd: bepHex('D8F1D8'), icon: 'Fill/Success', minW:120 },
    error:   { bg: bepHex('FFEEEE'), bd: bepHex('FFDFDD'), icon: 'Fill/Fail',    minW:120 },
    loading: { bg: BEP_C.white,      bd: null,              icon: 'Line/Loading', minW:106 },
  };
  var cfg = TYPES[type] || TYPES['info'];

  // 先量文字宽度
  var msgText = text || (type === 'loading' ? '加载中' : '消息提示');
  var tmpT = bepText(msgText, B, 14, { lh:22 });
  var textW = tmpT.width; tmpT.remove();

  var msgW = Math.max(cfg.minW, 16 + 16 + 8 + textW + 16);  // 左边距+图标+间距+文字+右边距
  var msgH = 40;

  var wrap = bepFrame(msgW, msgH, { name:'Message/' + type, clip:true });
  wrap.fills       = bepSolid(cfg.bg);
  wrap.cornerRadius = 2;
  wrap.strokes     = cfg.bd ? bepSolid(cfg.bd) : [];
  wrap.strokeWeight = cfg.bd ? 1 : 0;
  wrap.strokeAlign  = 'INSIDE';
  if (type === 'loading') {
    wrap.effects = [{
      type:'DROP_SHADOW',
      color:{ r:0, g:0, b:0, a:0.16 },
      offset:{ x:0, y:8 },
      radius:24,
      spread:0,
      visible:true,
      blendMode:'NORMAL'
    }];
  }

  var ico = bepIcon(cfg.icon, 16, null);
  if (ico) {
    if (type === 'loading') ico.name = 'LoadingRotating';
    ico.x = 16; ico.y = 12; wrap.appendChild(ico);
  }

  var t = bepText(msgText, B, 14, { lh:22, a:0.65 });
  t.x = 40; t.y = 9;
  wrap.appendChild(t);

  return wrap;
}

// ── § 13  警告提示 Alert（Figma实测：5.FeedBack/2.Alert警告提示）──────────────

/**
 * bepAlert — 页面内块状提示（普通/成功/警告/出错）
 *
 * title : 普通态为单行文案；大号态为标题
 * desc  : 大号态说明文字；普通态可传 null
 * opts  : { type:'info'|'success'|'warning'|'error'|'danger', variant:'normal'|'large',
 *           width, closable, actions:[{label}] }
 */
function bepAlert(title, desc, opts) {
  opts = opts || {};
  var type = opts.type || 'info';
  if (type === 'danger') type = 'error';
  var variant = opts.variant || (desc ? 'large' : 'normal');
  var width = opts.width || (variant === 'large' ? 959 : 680);
  var closable = opts.closable !== false;
  var actions = opts.actions || [];

  var TYPES = {
    info:    { bg:bepHex('E6F0F5'), bd:bepHex('CCE2EB'), icon:'Fill/Tips'     },
    success: { bg:bepHex('EBF8EC'), bd:bepHex('D8F1D8'), icon:'Fill/Success'  },
    warning: { bg:bepHex('FFF6EC'), bd:bepHex('FFEDDA'), icon:'Fill/Abnormal' },
    error:   { bg:bepHex('FFEEEE'), bd:bepHex('FFDFDD'), icon:'Fill/Fail'     }
  };
  var cfg = TYPES[type] || TYPES.info;

  var isLarge = variant === 'large';
  var h = isLarge ? (actions.length ? 104 : 82) : 40;
  var wrap = bepFrame(width, h, { name:'Alert/' + type + '/' + variant, r:2, clip:true });
  wrap.fills = bepSolid(cfg.bg);
  wrap.strokes = bepSolid(cfg.bd);
  wrap.strokeWeight = 1;
  wrap.strokeAlign = 'INSIDE';

  var icon = bepIcon(cfg.icon, 24, null);
  if (icon) {
    icon.x = 24;
    icon.y = isLarge ? 20 : 8;
    wrap.appendChild(icon);
  }

  if (isLarge) {
    var titleText = bepText(title || '提示标题', B, 16, { style:'Medium', lh:24, a:0.85 });
    titleText.x = 64; titleText.y = 16;
    wrap.appendChild(titleText);

    var descText = bepText(desc || '文字说明文字说明文字说明。', B, 14, {
      lh:22,
      a:0.65,
      w:Math.max(120, width - 64 - (closable ? 56 : 24))
    });
    descText.x = 64; descText.y = 46;
    wrap.appendChild(descText);

    if (actions.length) {
      var ax = 64;
      for (var i = 0; i < actions.length; i++) {
        var act = bepText(actions[i].label || String(actions[i]), BEP_C.primary, 14, { lh:22 });
        act.x = ax;
        act.y = 75;
        wrap.appendChild(act);
        ax += act.width + 18;
      }
    }
  } else {
    var text = bepText(title || '这是一条普通提示的文案', B, 14, {
      lh:22,
      a:0.65,
      w:Math.max(120, width - 64 - (closable ? 56 : 24))
    });
    text.x = 64; text.y = 9;
    wrap.appendChild(text);
  }

  if (closable) {
    var closeIco = bepIcon('Line/Close', 16, BEP_C.primary);
    if (closeIco) {
      closeIco.x = width - 32;
      closeIco.y = isLarge ? 20 : 12;
      wrap.appendChild(closeIco);
    }
  }

  return wrap;
}

